window.__SUM[16]={"LR000002":{"pair":"ACE -> BDKRB2","headline":"ACE and the B2 bradykinin receptor co-immunoprecipitate in CHO cells; this is a membrane complex, not shown to be agonist-receptor signalling.","interaction_type":"conflicting","direction_and_effect":"ACE is not shown to activate B2. ACE inhibitors resensitised B2 desensitised by bradykinin only when ACE (wild-type or cytoplasm-deleted) was co-expressed; GPI-anchored ACE did not allow resensitisation [PMID:10748135].","molecular_requirements":"Resensitisation needs enzyme and receptor close together on the membrane, and was lost when GPI-ACE was sequestered in cholesterol-rich domains; filipin restored it [PMID:10748135].","affinity_potency":[],"species_and_systems":"Human receptor and ACE expressed in Chinese hamster ovary cells [PMID:10748135].","localisation_and_range":"ACE is flagged secreted and BDKRB2 receptor/transmembrane [flag]; the paper places the interaction on the cell membrane [PMID:10748135].","caveats":"The abstract says co-IP 'suggesting an interaction', and a bridging partner cannot be excluded; one paper, abstract only. BioGRID lists affinity capture-western and FRET records from a different paper [DB:BioGRID].","key_references":[{"PMID":"10748135","why":"ACE/B2 co-IP and membrane-domain dependence of ACE-inhibitor action"}],"covers":["LR000002","LR003552"]},"LR000011":{"pair":"ADAM15 -> ITGB3","headline":"Integrin beta3 appears as the partner of alphav in ADAM15 binding in two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"D-15 specifically interacts with alphavbeta3 [PMID:9516430]; metargidin functions as a cell adhesion molecule via alphavbeta3 and alpha5beta1 [PMID:9914169].","molecular_requirements":"Chain-only evidence: the receptor is the alphavbeta3 heterodimer; changing the RGD flanking sequence also permits alphaIIbbeta3 binding [PMID:9516430].","affinity_potency":[],"species_and_systems":"Bacterially expressed D-15 on cells with recombinant integrins [PMID:9516430]; ADAM15-Fc with human cell lines and purified integrins [PMID:9914169].","localisation_and_range":"ADAM15 flagged not secreted [flag].","caveats":"Abstract only. IntAct lists an ELISA record [DB:IntAct]. One further judged row was abstract-insufficient.","key_references":[{"PMID":"9516430","why":"D-15 binds alphavbeta3 specifically"},{"PMID":"9914169","why":"ADAM15-alphavbeta3 adhesion on U937 cells"}],"covers":["LR000011","LR003561"]},"LR000020":{"pair":"ADAM2 -> ITGB7","headline":"ITGB7 is the beta subunit mediating RPMI 8866 cell adhesion to ADAM2 in human cell-line assays; full text read.","interaction_type":"direct binding","direction_and_effect":"ITGB7 siRNA knockdown reduced RPMI 8866 adhesion to ADAM2 to baseline, and an anti-ITGB7 antibody inhibited adhesion by 86% [PMID:21060781]. Curator label: agonist.","molecular_requirements":"ITGB7 pairs with ITGA9 (novel ITGA9-ITGB7) and ITGA4 in these cells; combined anti-ITGA9 plus anti-ITGA4 inhibited 88% [PMID:21060781].","affinity_potency":[],"species_and_systems":"Human RPMI 8866 cells, recombinant ADAM2 at 50 \u00b5g/ml; ITGB7 mRNA reduced to an average of 23% by siRNA [PMID:21060781].","localisation_and_range":"ADAM2 flagged non-secreted [flag]; adhesion to immobilised ADAM2.","caveats":"Adhesion assays, not purified binding. ITGB7 not detected in mouse oocytes by RT-PCR [PMID:21060781], so relevance to mouse eggs is unsupported; the mouse pair is ortholog-inferred.","key_references":[{"PMID":"21060781","why":"ITGB7 mediates adhesion to ADAM2"}],"covers":["LR000020","LR003570"]},"LR005399":{"pair":"ADAM28 -> ITGB1","headline":"ADAM28 disintegrin domain adhesion to Jurkat cells is blocked by anti-beta1 antibody; functional, human, abstract only.","interaction_type":"functional only","direction_and_effect":"Adhesion of Jurkat cells to the MDC-L (ADAM 28) disintegrin domain was inhibited by anti-alpha4 and anti-beta1 function-blocking mAbs; alpha4beta1-transfected K562 cells adhered [PMID:11724793].","molecular_requirements":"Beta1 acts as the partner of alpha4 (alpha4beta1) [PMID:11724793]; beta1 alone is not tested.","affinity_potency":[],"species_and_systems":"Human; Jurkat cells and K562 transfectants with recombinant Fc fusion [PMID:11724793]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM28 is flagged secreted [flag], but the paper says MDC-L is expressed on the surface of human lymphocytes [PMID:11724793].","caveats":"Abstract read only; adhesion assays.","key_references":[{"PMID":"11724793","why":"ADAM28 disintegrin recognised by alpha4beta1"}],"covers":["LR002073","LR005399"]},"LR008198":{"pair":"ADAM9 -> ITGA1:ITGB1","headline":"ADAM9 disintegrin adhesion is blocked by anti-alpha1 and anti-beta1 antibodies; no direct capture of alpha1.","interaction_type":"functional only","direction_and_effect":"Antibodies to alpha1, alpha3, alpha6, alphav and beta1 blocked HEK-293 adhesion to GST-disintegrin protein [PMID:15361064].","molecular_requirements":"Complex alpha1beta1 is inferred from blocking antibodies; alpha1 was not recovered in the GST-disintegrin pulldown while beta1 was [PMID:15361064].","affinity_potency":[],"species_and_systems":"Human HEK-293 cells; renal cortical lysate [PMID:15361064].","localisation_and_range":"ADAM9 flagged secreted [flag]; basolateral on renal tubular cells per the paper [PMID:15361064].","caveats":"Abstract read only; functional blocking evidence only for alpha1.","key_references":[{"PMID":"15361064","why":"ADAM9 disintegrin and beta1 integrins"}],"covers":["LR008198"]},"LR007946":{"pair":"ADIPOQ -> ADIPOR1:ADIPOR2","headline":"Adiponectin with an AdipoR1:AdipoR2 complex rests on database records only; curated papers were insufficient.","interaction_type":"database-asserted only","direction_and_effect":"UniProt lists each of ADIPOR1 and ADIPOR2 as receptors for ADIPOQ [DB:UniProt]. Reactome describes an ADIPOQ trimer binding ADIPOR dimers [DB:Reactome].","molecular_requirements":"A heteromeric AdipoR1:AdipoR2 receptor is not shown in our evidence; records describe the single receptors or dimers [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species not stated in our evidence.","localisation_and_range":"Adiponectin is flagged secreted [flag]; receptor transmembrane [flag].","caveats":"No curator-confirmed paper; two judged rows were abstract_insufficient. The pairing of both receptors as one complex may be a database artefact (an HGNC name match is also listed [DB:HGNC approved name]).","key_references":[],"covers":["LR007946"]},"LR003599":{"pair":"AHSG -> INSR","headline":"Purified human AHSG inhibits insulin receptor kinase activity without competing with insulin for binding; evidence is functional, one 1993 paper.","interaction_type":"functional only","direction_and_effect":"AHSG acts as an inhibitor of the insulin receptor tyrosine kinase: it blocked insulin-stimulated IR autophosphorylation in vitro and in vivo, substrate phosphorylation, IRS-1 phosphorylation and IRS-1/p85 association, and insulin-dependent mitogenesis [PMID:7906861].","molecular_requirements":"Not reported in our evidence. AHSG does not compete with insulin for IR binding and does not affect IGF-I-stimulated kinase activity [PMID:7906861].","affinity_potency":[],"species_and_systems":"Serum-purified human AHSG; effects in H-35 hepatoma cells and in vitro kinase assays; species of the cells is not stated in our evidence [PMID:7906861].","localisation_and_range":"AHSG is flagged secreted and INSR a transmembrane receptor [flag]; BioGRID lists a reconstituted complex [DB:BioGRID 278041].","caveats":"Not a classical ligand-site interaction: it acts at the kinase level and not by competing with insulin [PMID:7906861]. No direct binding or affinity data in our evidence beyond a BioGRID record. Abstract only; single paper.","key_references":[{"PMID":"7906861","why":"AHSG inhibits IR tyrosine kinase, not competing with insulin"}],"covers":["LR000049","LR003599"]},"LR007937":{"pair":"ARTN -> GFRA1:RET","headline":"Functional activation of GFRalpha1-RET by Artemin in one abstract-read paper, as a secondary receptor.","interaction_type":"functional only","direction_and_effect":"Artemin can activate the GFRalpha1-RET complex and supports survival of dopaminergic midbrain neurons in culture; agonist [PMID:9883723].","molecular_requirements":"Both GFRA1 and RET are in the complex [PMID:9883723]. UniProt says Artemin acts via coreceptor GFRA3 and RET [DB:UniProt]. A cryo-EM structure covers ARTN with GFRA3 [DB:PDB 6Q2S].","affinity_potency":[],"species_and_systems":"Cultured neurons; species not stated in the abstract [PMID:9883723].","localisation_and_range":"ARTN flagged secreted [flag].","caveats":"Abstract only; preferred receptor is GFRalpha3-RET. Structural records concern GFRA3, not GFRA1.","key_references":[{"PMID":"9883723","why":"Artemin activation of GFRalpha1-RET"}],"covers":["LR007937"]},"LR009719":{"pair":"B2M -> KIR3DL1","headline":"B2M-KIR3DL1 rests on crystal structures of the receptor with HLA-B ligands, not on direct B2M binding.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence for B2M; structures of KIR3DL1 with HLA-B*5701 [DB:PDB 3VH8] and Reactome HLA Bw4 with KIR3DL1 [DB:Reactome R-HSA-199566].","molecular_requirements":"Complex includes HLA-B and B2M chains [DB:PDB 3VH8]; B2M contact is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in the database records; no paper-level evidence in our evidence set.","localisation_and_range":"B2M is flagged secreted [flag]; the receptor is flagged transmembrane [flag]; range is otherwise not reported in our evidence.","caveats":"No curator-verified paper supports this pair; it rests on database records alone (PDB (34 records), Reactome). ","key_references":[],"covers":["LR009719"]},"LR009566":{"pair":"B2M -> LILRB1","headline":"A 3.4 A crystal structure shows LILRB1 (LIR-1) contacting B2M within HLA-A2; B2M is a contact surface of the MHC class I ligand.","interaction_type":"direct binding","direction_and_effect":"LIR-1 is an inhibitory receptor; the complex structure shows LIR-1 contacts the mostly conserved beta(2)-microglobulin and alpha3 domains of HLA-A2 [PMID:12897781].","molecular_requirements":"The LIR-1 D1D2 domains bind a site at the interdomain hinge plus a patch at the D1 tip; the ligand in the structure is HLA-A2 heavy chain with B2M, not B2M alone [PMID:12897781]. UniProt for LILRB1 says it recognises HLA-G in complex with B2M and a nonamer self-peptide [DB:UniProt Q8NHL6].","affinity_potency":[],"species_and_systems":"Human proteins, X-ray crystallography at 3.4 A [PMID:12897781]; also SPR entry [DB:IntAct P61769-Q8NHL6].","localisation_and_range":"Both partners are flagged: B2M secreted, LILRB1 transmembrane receptor [flag]; the ligand acts as part of membrane MHC class I, which implies contact signalling, though not stated in the paper.","caveats":"Single paper read as abstract only; B2M is binding surface in a pMHC, so a B2M-alone ligand role is not shown. Affinity not reported in our evidence.","key_references":[{"PMID":"12897781","why":"Crystal structure of LIR-1 D1D2 bound to HLA-A2, with B2M contacts"}],"covers":["LR009566"]},"LR000101":{"pair":"BDNF -> NTRK2","headline":"BDNF binds and activates TrkB (NTRK2); supported by binding-domain mapping, a functional synaptic study and several databases.","interaction_type":"direct binding","direction_and_effect":"BDNF is an agonist of NTRK2. Binding domains: two regions of the TrkB extracellular domain each bind BDNF independently [PMID:9312147]. BDNF rapidly enhances synaptic transmission in cultured hippocampal neurons, and the postsynaptic amplitude increase is blocked by the Trk inhibitor K-252a [PMID:7644540]. NT-4/5 is a preferred TrkB ligand, and BDNF is a preferred ligand for TrkB [PMID:7679912]. Reactome lists phosphorylated BDNF:NTRK2 homodimer complexes [DB:Reactome]. UniProt: BDNF binds NTRK2 [DB:UniProt].","molecular_requirements":"Residues 103-181 (third leucine-rich motif and second cysteine cluster) and the region near the second Ig-like domain (residues 342-394) each bind BDNF; Phe347, Asp354 and Tyr361 are involved [PMID:9312147]. Reactome shows homodimer complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human TrkB extracellular domain expressed in CHO cells [PMID:9312147]; cultured hippocampal neurons [PMID:7644540]; neuronal and nonneuronal cells expressing defined Trk receptors [PMID:7679912]. All read as abstracts only.","localisation_and_range":"BDNF has a secreted flag; NTRK2 has a transmembrane flag [flag].","caveats":"All three papers are abstract-only. No affinity values are given in the dossier. The 1995 paper reports a TrkB inhibitor effect, indirect evidence for the receptor.","key_references":[{"PMID":"9312147","why":"maps two BDNF-binding domains in human TrkB extracellular domain"},{"PMID":"7679912","why":"neurotrophin-Trk specificities; BDNF preferred TrkB ligand"},{"PMID":"7644540","why":"BDNF acute synaptic effect blocked by TrkB inhibitor K-252a"}],"covers":["LR000101","LR003650"]},"LR005489":{"pair":"BGN -> CD44","headline":"Biglycan signals through CD44 with TLR4 in macrophages; CD44 is a co-receptor, with no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Biglycan triggers autophagy in macrophages; macrophages lacking TLR2/TLR4, CD14 or CD44 show that the pro-autophagy signal required TLR4 interaction with CD44 [PMID:30712922]. The authors call CD44 a novel signalling co-receptor for biglycan [PMID:30712922]. In vivo, the biglycan-CD44 interaction increased M1 autophagy and renal M2 macrophage numbers and reduced tubular damage after ischemia/reperfusion injury [PMID:30712922].","molecular_requirements":"TLR4 plus CD44 are needed for the autophagy signal; CD44 acts with TLR4, not alone [PMID:30712922].","affinity_potency":[],"species_and_systems":"Murine macrophages and mice, including knockouts; soluble biglycan also promoted autophagy in human peripheral blood macrophages [PMID:30712922]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Soluble biglycan (secreted flag) acting on macrophages; CD44 has transmembrane and secreted flags [flag].","caveats":"Abstract-only; genetic loss-of-function, no direct binding or affinity. CD44 acts as co-receptor with TLR4, so scoring biglycan -> CD44 alone may overstate.","key_references":[{"PMID":"30712922","why":"CD44/TLR4 axis required for biglycan-induced autophagy"}],"covers":["LR002175","LR005489"]},"LR000110":{"pair":"BMP10 -> ENG","headline":"Direct binding shown by SPR for soluble endoglin; it acts as an inhibitory decoy for BMP10, not a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"Mouse and human endoglin ECD-Fc bound BMP9 and BMP10 directly, specifically and with high affinity in SPR (Biacore) and cell-based assays; the ECD-Fc is anti-angiogenic, reducing VEGF-induced vessel formation and tumour burden [PMID:21737454]. Curators classify it as an antagonist/decoy.","molecular_requirements":"The BMP9/BMP10 binding site is the orphan domain, residues 26-359 of human endoglin; endoglin and type II receptors bind overlapping sites on BMP9 [PMID:21737454].","affinity_potency":[],"species_and_systems":"Recombinant ECD-Fc fusions, chick chorioallantoic membrane and mouse tumour models [PMID:21737454]. Curators annotate human ligand and receptor; mouse pair is ortholog-inferred.","localisation_and_range":"The tested form is the soluble extracellular domain; membrane endoglin was not tested for BMP10 here. BMP10 is annotated as secreted [flag]. UniProt records the BMP10-ENG interaction citing this paper [DB:UniProt].","caveats":"Abstract read only; no affinity number in our evidence. The overlapping-site result is stated for BMP9, not BMP10. One further row is still pending.","key_references":[{"PMID":"21737454","why":"Soluble endoglin binds BMP9/BMP10 via orphan domain"}],"covers":["LR000110","LR003659"]},"LR006785":{"pair":"BMP5 -> ACVRL1","headline":"BMP5 to ACVRL1 rests on a GtoPdb agonist assertion only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb].","molecular_requirements":"Single receptor chain; coreceptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Screened papers: 1 different_entity, 3 abstract_insufficient. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR006785"]},"LR005498":{"pair":"BMP6 -> ACVRL1","headline":"Curated paper found BMP6 does not bind endogenous ALK-1; only a database agonist record supports the pair.","interaction_type":"conflicting","direction_and_effect":"GtoPdb lists BMP6 as an agonist at ACVRL1 [DB:GtoPdb]. The one verified paper concluded ALK-1 is not a physiological BMP-6 receptor [PMID:10504300].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"The paper used COS-7 overexpression and endogenous cells (HUVEC); human versus other origin of reagents is not stated in the dossier. Pair is listed for human and mouse, both projected from other evidence [flag].","localisation_and_range":"BMP6 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Negative result: endogenous ALK-1-expressing HUVEC cells did not bind BMP-6; weak binding seen only in COS-7 overexpression was judged an overexpression artifact [PMID:10504300]. The paper's abstract reports binding of BMP-6 to ALK-2, BMPR-IA and BMPR-IB, not ALK-1. Six other papers were abstract-insufficient. Treat as unlikely to be a bona fide receptor for CCC scoring.","key_references":[{"PMID":"10504300","why":"Verified negative: ALK-1 not a physiological BMP-6 receptor"}],"covers":["LR002184","LR005498"]},"LR003689":{"pair":"BMP7 -> ACVR2A","headline":"BMP7 binds the activin type II receptor ACVR2A directly; supported by a crystal structure, SPR and cell-binding data.","interaction_type":"direct binding","direction_and_effect":"BMP7 binds ACVR2A (ActR-II) as a type II receptor; a crystal structure of BMP7 with the ActRII extracellular domain was solved [PMID:12667445]. ActR-II acts as a functional type II receptor for BMP7 (OP-1): transcription was activated when OP-1 bound ActR-I plus ActR-II, or BMPR-IB plus ActR-II [PMID:7790373]. In P19 cells BMP7 and activin bind the same type II receptors, ActRII and IIB, but BMP7 recruits ALK2 as its main type I receptor [PMID:9748228]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"ACVR2A is the type II chain; a type I receptor is also needed for signalling. The structure shows type I and type II ECDs make no direct contact, yet cooperative assembly occurs, and BMP7 affinity for its low-affinity type I receptor ECD rises 5-fold with the type II ECD present [PMID:12667445]. OP-1 binding to type I receptors was observed in the presence of ActR-II [PMID:7790373].","affinity_potency":[{"value":"KD(eq) 8.0 nM","assay":"SPR, immobilised ActR-II ECD, soluble BMP7","system":"recombinant human proteins","cite":"PMID:19735544"}],"species_and_systems":"Human recombinant proteins for the structure and SPR [PMID:12667445][PMID:19735544]; P19 embryonal carcinoma cells [PMID:9748228]; species of the OP-1 binding study not specified [PMID:7790373]. The dossier covers human and mouse pairs; the mouse pair is not ortholog-inferred, but no mouse-specific experiments are shown.","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Two papers (PMID 7790373, 9748228) were read as abstracts only. One further paper was judged abstract_insufficient. The OP-1 abstract reports ActR-II affinity as two- to threefold lower than that of activin A [PMID:7790373].","key_references":[{"PMID":"12667445","why":"Crystal structure of BMP7 with ActRII ECD and cooperative assembly"},{"PMID":"19735544","why":"SPR affinities of BMP7 for type I and II receptor ectodomains"},{"PMID":"7790373","why":"OP-1 binds ActR-II and signals with type I partners"}],"covers":["LR000140","LR003689"]},"LR003698":{"pair":"BTC -> ERBB4","headline":"BTC activates ERBB4 in two functional papers; no affinity of its own, plus GtoPdb and Reactome records.","interaction_type":"functional only","direction_and_effect":"Betacellulin activates EGFR and erbB-4 and gives cellular response patterns distinct from EGF or neuregulin-beta [PMID:8570211]. In human aortic smooth muscle cells, ErbB4 and EGFR are expressed and BTC is mitogenic, suggesting EGF-family signalling [PMID:11254912]. Annotation: Stimulatory.","molecular_requirements":"ErbB4 may act with EGFR; combination requirements are not reported in our evidence. PDB 8U4J and 8U4K list BTC with an ERBB4 chain [DB:PDB 8U4J].","affinity_potency":[],"species_and_systems":"Human cells (aortic smooth muscle cells) [PMID:11254912]; cell system of 8570211 not reported in our evidence. Mouse pair is ortholog-inferred.","localisation_and_range":"BTC is flagged secreted and transmembrane; ERBB4 transmembrane [flag].","caveats":"Both verified papers are functional and read at abstract level; one is co-expression with immunohistochemistry only. GtoPdb has a pIC50 record without value shown [DB:GtoPdb]. One paper is pending.","key_references":[{"PMID":"8570211","why":"BTC activates EGFR and erbB-4."},{"PMID":"11254912","why":"BTC mitogenic with EGFR and ErbB4 on human aortic smooth muscle cells."}],"covers":["LR000149","LR003698"]},"LR008468":{"pair":"CALM3 -> PDE1A","headline":"CALM3 activates PDE1A according to GtoPdb only; no curated paper supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CALM3 as an activator of PDE1A (Type=Activator; Action=Activation), and the interaction is annotated Stimulatory [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human entities; no experimental system or species of assay is reported in our evidence.","localisation_and_range":"Not reported in our evidence; no localisation flag is given for the ligand.","caveats":"Support rests on a database record alone, with no affinity (Affinity Units=-) and no verified primary paper. The one judged paper concerned a different entity. Calmodulin acts here as a Ca2+-sensor regulator of an enzyme rather than a classical secreted ligand; the receptor label comes from an annotation flag [flag].","key_references":[],"covers":["LR008468"]},"LR009386":{"pair":"CAMP -> IGF1R","headline":"LL-37 is described as a biased agonist of IGF1R; one confirmed abstract plus co-IP/ELISA records.","interaction_type":"conflicting","direction_and_effect":"LL37 is described as a biased agonist of IGF1R; it does not promote IRS1 recruitment to IGF1R as IGF1 does, and its bias depends on beta-arrestin 2 [PMID:29499305]. It promoted cell proliferation but not protein synthesis [PMID:29499305].","molecular_requirements":"Beta-arrestin 2 is needed for the biased signalling and LL37 changes IGF1R association with GRK6 [PMID:29499305]. The need for other subunits is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell-based BRET and proliferation assays; the cell type and species are not reported in our evidence [PMID:29499305]. BioGRID and IntAct record reconstituted complex, Western capture, ELISA and co-IP in PMID 21685939 [DB:BioGRID] [DB:IntAct].","localisation_and_range":"CAMP is flagged secreted and IGF1R transmembrane [flag].","caveats":"The confirmed paper was read as an abstract; it builds on prior work calling LL37 a biased agonist. Two judged papers concerned a different entity and one was review-only. The 'conflicting' label reflects that LL37 acts through some IGF1R pathways but not others, not a negative result. Binding evidence sits in database records from PMID 21685939 only.","key_references":[{"PMID":"29499305","why":"Mechanism of LL37 biased agonism at IGF1R"}],"covers":["LR009386"]},"LR000200":{"pair":"CCL16 -> CCR1","headline":"CCL16 is a low-affinity functional ligand of human CCR1 in two transfected-cell studies, with database support from Reactome.","interaction_type":"direct binding","direction_and_effect":"CCL16 (LEC) bound and activated CCR1-transfected HEK-293 cells [PMID:10910894]; calcium mobilisation and chemotaxis via CCR1 at relatively high concentrations [PMID:11470772]. Agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor in HEK-293 cells [PMID:10910894] and mouse L1.2 pre-B cells expressing human receptors [PMID:11470772]; abstract-level reading.","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Low affinity; maximal migration at 89.3 nmol/L, 20- to 200-fold more than RANTES or I309 [PMID:10910894]. The two papers differ on other receptors (CCR8 vs CCR2/CCR5). Reactome lists CCR1, 2 and 8 binding CCL16 [DB:Reactome].","key_references":[{"PMID":"10910894","why":"Binding and chemotaxis at CCR1 and CCR8"},{"PMID":"11470772","why":"12-receptor panel; low-affinity CCR1 ligand"}],"covers":["LR000200"]},"LR003779":{"pair":"CCL7 -> CCR3","headline":"MCP-3 (CCL7) binds human CCR3 with Kd 2.7 nM in three papers, but is a weaker activator than eotaxin or RANTES.","interaction_type":"direct binding","direction_and_effect":"CCR3 bound MCP-3 with Kd 2.7 nM; eotaxin, RANTES and, to a lesser extent, MCP-3 stimulated a Ca2+ flux [PMID:8642344]. CKR-3 transfectants bound MCP-3 and migrated to it in chemotaxis [PMID:8676064]. An antagonistic anti-CCR3 antibody showed over 95% of eosinophil responses to MCP-3 and other CC chemokines were CCR3-mediated [PMID:9005985]. GtoPdb: full agonist, pKi 8.6 to 9.2 [DB:GtoPdb].","molecular_requirements":"CCR3 alone suffices in transfectants; MCP-3 is only a partial/lesser activator versus eotaxin [PMID:8642344].","affinity_potency":[{"value":"Kd 2.7 nM","assay":"radioligand binding","system":"CCR3 in AML14.3D10 cells (human)","cite":"PMID:8642344"},{"value":"pKi 8.6 to 9.2","assay":"GtoPdb binding range","system":"human CCR3","cite":"DB:GtoPdb"}],"species_and_systems":"Human ligand and receptor; transfectants and primary human eosinophils [PMID:8642344][PMID:9005985]. Mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; CCR3 flagged transmembrane receptor [flag].","caveats":"Two of three papers read as abstracts; first is full text. CCR3 is promiscuous so the pair is individually low-specificity.","key_references":[{"PMID":"8642344","why":"CCR3 cloned; MCP-3 Kd 2.7 nM"},{"PMID":"8676064","why":"CKR-3 binds and chemotaxes to MCP-3"},{"PMID":"9005985","why":"Over 95% of eosinophil MCP-3 response via CCR3"}],"covers":["LR000269","LR003779"]},"LR003788":{"pair":"CCL8 -> ACKR1","headline":"Human ACKR1 (Duffy) binds CCL8 weakly (Ki 151 nM) in one paper and moderately in a second competition assay.","interaction_type":"direct binding","direction_and_effect":"CCL8 bound Duffy on erythrocytes in the weak-binding category (Ki 100 nM to 1 uM) [PMID:15358176]. In DARC-expressing cells, 125I-CXCL1 binding was moderately inhibited by CCL17 and CCL8 and strongly by CCL7, CCL5 and CCL2 [PMID:13679391]. Signalling not reported for CCL8.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 151.0 nM","assay":"125I-CXCL8 displacement binding","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes and DARC-expressing cells [PMID:15358176][PMID:13679391]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL8 flagged secreted; ACKR1 flagged transmembrane receptor [flag].","caveats":"The 2003 evidence is a browser-read results sentence, unverified. The 2004 evidence sentence ('those that showed strong binding') does not match the weak-binding category in the curator's assay detail.","key_references":[{"PMID":"15358176","why":"CCL8 weak binder at Duffy, Ki 151.0 nM"},{"PMID":"13679391","why":"CCL8 moderately inhibits CXCL1 binding to DARC"}],"covers":["LR000278","LR003788"]},"LR005579":{"pair":"CCN3 -> ITGAV","headline":"CCN3 binds integrin alphavbeta3 directly (half-maximal binding 10 nM); supported by full text and databases.","interaction_type":"direct binding","direction_and_effect":"CCN3 acts as an agonist, supporting HUVEC adhesion and migration through alphavbeta3 [PMID:12695522]. CCN3 binds directly to immobilized integrins alphavbeta3 and alpha5beta1 with half-maximal binding at 10 nM and 50 nM CCN3 respectively [PMID:12695522].","molecular_requirements":"The receptor is the alphavbeta3 heterodimer; UniProt lists ITGAV:ITGB3 and ITGAV:ITGB5 as CCN3 partners [DB:UniProt]. The paper shows binding for alphavbeta3 only [PMID:12695522]. Adhesion by alphavbeta3 was only partly blocked by the LM609 antibody [PMID:12695522].","affinity_potency":[{"value":"10 nM","assay":"half-maximal binding (EC50), solid-phase ELISA with immobilized alphavbeta3","system":"purified integrin, recombinant human CCN3","cite":"PMID:12695522"}],"species_and_systems":"Recombinant human CCN3 (baculovirus-expressed) and purified integrins; HUVEC cells; rat cornea angiogenesis assay [PMID:12695522].","localisation_and_range":"CCN3 is a matricellular protein, and its adhesion activity is shown on coated protein [PMID:12695522]; a secretion annotation for CCN3 is not in our dossier.","caveats":"Single primary paper; UniProt and GtoPdb cite it [DB:UniProt][DB:GtoPdb]. UniProt also lists ITGAV:ITGB5, which the dossier does not detail.","key_references":[{"PMID":"12695522","why":"Direct CCN3-integrin binding and HUVEC adhesion, migration and angiogenesis"}],"covers":["LR002278","LR005579"]},"LR008477":{"pair":"CD14 -> TLR4","headline":"CD14 delivers LPS to the LY96/TLR4 complex per databases; no verified primary paper in this dossier.","interaction_type":"database-asserted only","direction_and_effect":"CD14, together with LBP, binds monomeric LPS and delivers it to the LY96/TLR4 complex, mediating the innate response to LPS [DB:UniProt]. Reactome has a reaction 'Transfer of LPS onto TLR4' [DB:Reactome R-HSA-166041].","molecular_requirements":"CD14, LY96 and TLR4 form the LPS receptor multi-protein complex; LY96 is needed in addition to TLR4 [DB:UniProt][DB:Reactome R-HSA-166850].","affinity_potency":[],"species_and_systems":"Species and system are not reported in our evidence.","localisation_and_range":"CD14 is flagged secreted and a receptor [flag]; the UniProt text describes cell-surface delivery of LPS.","caveats":"The relationship is ligand-delivery (LPS co-receptor), not shown as direct CD14-TLR4 binding. No verified paper (review_only 1, abstract_insufficient 5).","key_references":[],"covers":["LR008477"]},"LR008972":{"pair":"CD14 -> TLR6","headline":"CD14 is described as a co-receptor for the TLR2:TLR6 heterodimer by UniProt only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"CD14 acts as a coreceptor for the TLR2:TLR6 heterodimer for diacylated lipopeptides [DB:UniProt].","molecular_requirements":"The interacting unit is the TLR2:TLR6 heterodimer, so TLR2 is also needed [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species and system are not reported in our evidence.","localisation_and_range":"Not reported in our evidence beyond the CD14 flags [flag].","caveats":"Database text only; no verified paper (review_only 2). CD14 is a co-receptor here rather than a ligand, so the pair's direction is questionable.","key_references":[],"covers":["LR008972"]},"LR005588":{"pair":"CD40LG -> ITGA5","headline":"Soluble CD40L binds alpha5beta1 integrin, with lower affinity than for alphaIIbbeta3; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"CD154 bound alpha5beta1 with about 4-fold lower affinity than alphaIIbbeta3, and sCD154 bound CD40 and alpha5beta1 simultaneously on U937 cells, activating p38 and ERK1/2 and synergising in MMP-2/MMP-9 release [PMID:22461623]. sCD40L activated soluble alpha5beta1 in cell-free conditions [PMID:33571526].","molecular_requirements":"Evidence is for the alpha5beta1 heterodimer, not ITGA5 alone. CD154 mutants that lost CD40 or alphaIIbbeta3 binding still bound alpha5beta1 [PMID:22461623]. UniProt: ITGA5:ITGB3 is a receptor for soluble CD40LG [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human U937 cells [PMID:22461623]; soluble integrins and CHO cells [PMID:33571526]; mouse pair projected.","localisation_and_range":"CD40LG flagged secreted [flag]; soluble form acts at a distance [PMID:33571526].","caveats":"Both papers read as abstracts (one marked full text); no absolute affinity values reported; chain-only attribution.","key_references":[{"PMID":"22461623","why":"CD154 binds alpha5beta1, simultaneous with CD40"},{"PMID":"33571526","why":"sCD40L activates alpha5beta1"}],"covers":["LR002289","LR005588"]},"LR007955":{"pair":"CD40LG -> ITGA5:ITGB1","headline":"CD40L binding to integrin alpha5beta1, supported by one abstract-level binding paper plus a UniProt note.","interaction_type":"direct binding","direction_and_effect":"CD154 (CD40L) is reported to bind alpha5beta1 in addition to its classical receptor CD40, and soluble CD154 can engage CD40 and alpha5beta1 at the same time; joint engagement activated p38 and ERK1/2 and synergised in MMP-2/-9 release [PMID:22461623]. UniProt describes the integrin as a receptor for soluble CD40LG required for CD40/CD40LG signalling [DB:UniProt].","molecular_requirements":"Receptor is the alpha5:beta1 heterodimer. CD154 residues used for alpha5beta1 binding are distinct from those for CD40 or alphaIIbbeta3 [PMID:22461623]. The UniProt text names ITGA5:ITGB3, which does not match this pair [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human CD154 and human monocytic U937 cells expressing CD40 and alpha5beta1 [PMID:22461623].","localisation_and_range":"Ligand carries both secreted and transmembrane flags [flag]; the paper used soluble CD154 [PMID:22461623].","caveats":"Only one paper, read as an abstract only; no affinity for this pair is reported (the abstract gives only a ~4-fold weaker alpha5beta1 than alphaIIbbeta3 affinity) [PMID:22461623]. UniProt entry mentions ITGB3 rather than ITGB1 [DB:UniProt].","key_references":[{"PMID":"22461623","why":"Binding to alpha5beta1, simultaneous CD40 engagement, U937 cell signalling"}],"covers":["LR007955"]},"LR003797":{"pair":"CD5L -> CD5","headline":"Pair rests on one 1998 abstract describing a B-cell ligand called CD5L; its identity relative to this entity is unclear.","interaction_type":"direct binding","direction_and_effect":"CD5-Ig bound a B-cell ligand termed CD5L, not blocked by anti-CD72 mAb, and CD5-Ig induced proliferation of resting B cells [PMID:9723705].","molecular_requirements":"The ligand was composed of 77-80 and 38-40 kDa polypeptide chains in immunoprecipitates and was distinct from CD72 [PMID:9723705].","affinity_potency":[],"species_and_systems":"Splenic and peritoneal B cells and B lymphoma lines; species not stated in the abstract [PMID:9723705]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Appears to be a B-cell surface ligand [PMID:9723705]; annotation flags mark both partners as secreted [flag].","caveats":"Abstract-only; the paper does not clone or identify the molecule, so the link to the gene CD5L is not shown in our evidence. No databases or affinity.","key_references":[{"PMID":"9723705","why":"CD5-Ig binding to a B cell ligand named CD5L"}],"covers":["LR000288","LR003797"]},"LR006758":{"pair":"Cd99 -> Pilrb1","headline":"Mouse PILR-beta binds CD99 about 40 times more weakly than PILR-alpha (Kd approximately 85 \u03bcM); species labelled human.","interaction_type":"direct binding","direction_and_effect":"Activating PILR-beta binds CD99 with approximately 40 times lower affinity than PILR-alpha [PMID:18234675].","molecular_requirements":"PILR-beta binds the T50A mutant but not T45A, so it needs the Thr-45 O-glycosylation site [PMID:18234675].","affinity_potency":[{"value":"Kd approximately 85 \u03bcM","assay":"SPR","system":"PILRbeta with CD99","cite":"PMID:18234675"}],"species_and_systems":"Curator labelled experiments as human for both partners, while this pair is mouse [PMID:18234675].","localisation_and_range":"Membrane-bound CD99.","caveats":"Abstract only; very weak affinity; species mismatch.","key_references":[{"PMID":"18234675","why":"SPR of PILR-CD99 binding"}],"covers":["LR006758"]},"LR005597":{"pair":"CDCP1 -> CD6","headline":"CDCP1 (CD318) is reported as a CD6 ligand; one paper with KO mice and human synovium, one cancer paper.","interaction_type":"direct binding","direction_and_effect":"CD318 was identified as a CD6 ligand; CD318 KO mice are protected in EAE like CD6 KO mice, and CD318 participates in CD6-dependent adhesion of T cells to synovial fibroblasts [PMID:28760953]. CDCP1 binds CD6 and inhibits JAK-STAT in T cells, reducing CTL activity [PMID:39455095].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse KO and human synovial tissue and cells (species not stated for the binding itself) [PMID:28760953]; human cervical cancer and mouse tumour models [PMID:39455095].","localisation_and_range":"CDCP1 is annotated as secreted [flag]; soluble CD318 is chemoattractive to T cells and elevated in arthritis synovial fluid [PMID:28760953].","caveats":"Both papers read as abstract with limited excerpts; no database records. The second paper's binding evidence is a one-line statement [PMID:39455095].","key_references":[{"PMID":"28760953","why":"Identifies CD318 as CD6 ligand"},{"PMID":"39455095","why":"CDCP1-CD6 inhibits JAK-STAT in T cells"}],"covers":["LR002299","LR005597"]},"LR006839":{"pair":"CDH2 -> FCER2","headline":"Only an IntAct SPR record; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. IntAct lists P06734 - P19022 from a surface plasmon resonance assay [DB:IntAct] [PMID:35922511].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"FCER2 is flagged secreted, receptor and transmembrane, CDH2 transmembrane [flag]; actual form is not reported.","caveats":"No curator has judged any paper for this pair, so the SPR record is unverified and gives no values here.","key_references":[],"covers":["LR006839"]},"LR007964":{"pair":"CNTN1 -> MCAM","headline":"No curator-confirmed paper; only IntAct interaction records support this pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists co-immunoprecipitation (anti tag) and surface plasmon resonance records [DB:IntAct]; species not stated in our evidence.","localisation_and_range":"Contactin-1 is flagged transmembrane; MCAM annotation lists is_transmembrane 0 and is_receptor 1 [flag]. Class Adhesion-Adhesion.","caveats":"The one judged paper was abstract_insufficient, so no paper confirms it. Rests on database assertions alone.","key_references":[],"covers":["LR007964"]},"LR006884":{"pair":"COL18A1 -> ITGA2:ITGB1","headline":"Database-asserted only: BioGRID and IntAct record COL18A1-ITGB1 binding; no curator-confirmed paper for this specific integrin.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect: not reported in our evidence.","molecular_requirements":"Databases record binding to ITGB1 only, not to the specific alpha chain, so the alpha subunit requirement is unresolved [DB:BioGRID] [DB:IntAct].","affinity_potency":[],"species_and_systems":"BioGRID lists a reconstituted complex [DB:BioGRID, PMID:19542224]; IntAct lists a pull down [DB:IntAct, PMID:17615292]. Species not reported in our evidence.","localisation_and_range":"Ligand flagged as secreted; receptor is a transmembrane complex [flag].","caveats":"No papers were judged confirmed: curator read counts are review_only and different_entity only. The pair rests on database records alone, and these name ITGB1 and not the alpha chain.","key_references":[],"covers":["LR006884"]},"LR005669":{"pair":"COL2A1 -> OSCAR","headline":"OSCAR binds motifs in fibrillar collagens and costimulates osteoclastogenesis; one abstract-read paper, collagen II not singled out.","interaction_type":"direct binding","direction_and_effect":"OSCAR binds specific motifs within fibrillar collagens and this led to signalling that increased osteoclast numbers in culture [PMID:21841309]. Curator label: agonist.","molecular_requirements":"OSCAR signals through FcR gamma-associated ITAM pathways [PMID:21841309]; chain-specific requirements not reported.","affinity_potency":[],"species_and_systems":"Mouse and patient samples deficient in ITAM pathways; mouse rows marked ortholog-inferred though curators say both species were assayed [PMID:21841309].","localisation_and_range":"Matrix ligand, cell-surface receptor (flags).","caveats":"Abstract read only; 'fibrillar collagens' as a class, so COL2A1 specifically is not tested. No database records.","key_references":[{"PMID":"21841309","why":"OSCAR binds fibrillar collagen motifs"}],"covers":["LR002390","LR005669"]},"LR005678":{"pair":"COL4A2 -> DDR1","headline":"Direct but weak collagen IV binding and phosphorylation of DDR1 in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Collagen IV bound DDR1 and induced phosphorylation, weaker than fibril-forming collagens [PMID:9659900].","molecular_requirements":"No co-receptor requirement reported in our evidence. COL4A2 is inferred as a chain of the tested commercial type IV collagen, not tested alone [PMID:9659900].","affinity_potency":[],"species_and_systems":"Human-labelled ligand and receptor, slot-blot and phosphorylation assays; other species are projections [PMID:9659900].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Commercial type IV collagen is a generic preparation, probably mostly the COL4A1/COL4A2 heterotrimer, so binding cannot be assigned to one chain [PMID:9659900]. Binding was consistently weaker than to fibril-forming collagens [PMID:9659900]. No affinity values reported.","key_references":[{"PMID":"9659900","why":"Collagens as ligands of DDR receptors; type IV weaker than fibrillar"}],"covers":["LR002399","LR005678"]},"LR005687":{"pair":"COL4A3 -> ITGB5","headline":"COL4A3 NC1 binds alphaVbeta5 in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"alpha3NC1 binds alpha(v)beta(5) integrin, predominantly via its RGD site, and supports endothelial adhesion [PMID:14610079].","molecular_requirements":"The receptor is the alphaV:beta5 heterodimer; the domain tested is NC1 [PMID:14610079].","affinity_potency":[],"species_and_systems":"Recombinant human domain expressed in HEK293, endothelial cell assays [PMID:14610079].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Single abstract-only paper; no affinity values reported in our evidence.","key_references":[{"PMID":"14610079","why":"alpha3NC1 RGD site binds alphaVbeta3 and beta5"}],"covers":["LR002408","LR005687"]},"LR008585":{"pair":"COL6A1 -> ITGA2:ITGB1","headline":"Weak: one abstract reports COL6A1 binding ITGB1 in glioblastoma; the alpha subunit is not named.","interaction_type":"functional only","direction_and_effect":"COL6A1 is bound to ITGB1 on endothelial cells, disrupting tight junctions via UBD-mediated claudin-5 degradation [PMID:41297453].","molecular_requirements":"The paper names only ITGB1, not the alpha partner, so ITGA2:ITGB1 is not distinguished from other beta1 heterodimers [PMID:41297453].","affinity_potency":[],"species_and_systems":"Human patient-derived glioblastoma organoids and endothelial cells [PMID:41297453].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only; the binding wording is an abstract statement. No affinity reported. Other rows were review_only or abstract_insufficient.","key_references":[{"PMID":"41297453","why":"COL6A1 binds endothelial ITGB1 in TMZ-resistant glioblastoma"}],"covers":["LR008585"]},"LR003869":{"pair":"COL8A1 -> ITGA2","headline":"Antibody-blocking evidence that alpha2 integrin contributes to smooth muscle cell attachment to type VIII collagen; functional only.","interaction_type":"functional only","direction_and_effect":"Antibodies against alpha1 or alpha2 integrins reduced attachment of SMCs to type VIII collagen by 29% and 77%, respectively; anti-beta1 antibodies prevented attachment and migration [PMID:10666376]. Type VIII collagen signaled through integrins to stimulate MMP production [PMID:10666376].","molecular_requirements":"Beta1 integrin is implicated by antibody blocking; alpha1 and alpha2 were tested together as a pair of antibodies, so the effect of this chain alone is not separable in the evidence [PMID:10666376].","affinity_potency":[{"value":"29% and 77%","assay":"reduction of SMC attachment to type VIII collagen by anti-alpha1 or anti-alpha2 integrin antibodies, respectively","system":"smooth muscle cells","cite":"PMID:10666376"}],"species_and_systems":"Experiments used smooth muscle cells, with neointimal SMCs grown from rat [PMID:10666376]; the human and mouse pairs are ortholog-inferred from this evidence.","localisation_and_range":"Ligand flagged secreted [flag]; the paper describes matrix-deposited type VIII collagen [PMID:10666376].","caveats":"Abstract only; antibody blocking is indirect and does not show direct binding. A second confirmed paper exists but is not shown; one review-only and one abstract-insufficient row.","key_references":[{"PMID":"10666376","why":"Antibody blocking implicates alpha1/alpha2/beta1 integrins in SMC attachment to type VIII collagen"}],"covers":["LR000363","LR003869"]},"LR008657":{"pair":"COMP -> ITGB1","headline":"No verified paper; only a Reactome record naming the alpha5beta1 heterodimer supports this chain-level pair.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; one review_only and four abstract_insufficient papers, none confirmed.","molecular_requirements":"The Reactome record concerns Integrin alpha5beta1, so ITGB1 acts with an alpha chain; beta1 alone is not shown to bind [DB:Reactome R-HSA-2426259].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Chain-only entry for a heterodimer, no confirmed paper.","key_references":[],"covers":["LR008657"]},"LR003878":{"pair":"CRH -> CRHR1","headline":"CRH binds and activates CRHR1 with high affinity; well supported by binding, functional, structural and database evidence.","interaction_type":"direct binding","direction_and_effect":"CRH acts as a full agonist at CRHR1 [DB:GtoPdb]. Expressed human receptor bound rat/human CRF and coupled to adenylate cyclase; antagonist alpha-helCRF-(9-41) inhibited CRF-stimulated cAMP [PMID:7692441]. Agonists and antagonists give different apparent affinities depending on the radioligand [PMID:11123370]. In HEK293 cells hCRF1 mobilised calcium and coupled to Gs, but no calcium response occurred in SK-N-MC cells [PMID:15450949].","molecular_requirements":"Receptor regions: the third extracellular domain/fifth transmembrane junction is most important for CRF binding and activation; second extracellular domain residues play secondary roles [PMID:9178757]. An alternatively spliced form with a 29-amino-acid insert in the first intracellular loop is described [PMID:7692441]. Co-receptors not reported in our evidence.","affinity_potency":[{"value":"Kd = 3.3 +/- 0.45 nM","assay":"binding of rat/human CRF to expressed human receptor","system":"COS cells","cite":"PMID:7692441"},{"value":"Kd = 1.09 nM","assay":"binding of human/rat CRF to tree shrew CRF-R1","system":"HEK293 cells","cite":"PMID:9851694"},{"value":"pKd 7.099999904632568 to 9.0","assay":"GtoPdb curated affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptor in COS and HEK293 cells [PMID:7692441, PMID:15450949]. Tree shrew and Xenopus receptors were also tested [PMID:9851694, PMID:9326293]. The mouse pair is inferred from human evidence. Structures exist [DB:PDB 3EHT].","localisation_and_range":"CRH is flagged secreted and CRHR1 is flagged a receptor [flag].","caveats":"Most papers read as abstracts only. Xenopus CRF-R1 was very selective for ligands, unlike human CRF-R1, so cross-species pharmacology differs [PMID:9326293]. Signalling output depends on cell background [PMID:15450949]. One of the cited affinity values is from a non-human receptor.","key_references":[{"PMID":"7692441","why":"Cloning, Kd 3.3 nM, cAMP coupling"},{"PMID":"11123370","why":"Competitive binding with agonist and antagonist radioligands"},{"PMID":"9178757","why":"Maps receptor regions for CRF binding"}],"covers":["LR000372","LR003878"]},"LR011699":{"pair":"CSF2 -> CSF2:CSF2RA:CSF2RB","headline":"Complex-form row for GM-CSF with its alpha and beta receptor; no curator-verified papers, only database records.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GM-CSF as agonist at CSF2RA and at CSF2RB [DB:GtoPdb]. Reactome describes GM-CSF binding the alpha subunit and the alpha:GM-CSF complex then binding the beta chain [DB:Reactome R-HSA-913360] [DB:Reactome R-HSA-913371].","molecular_requirements":"Database records place alpha and beta chains together; a crystal structure of GM-CSF with receptor chains is recorded [DB:PDB 4NKQ] [DB:IntAct].","affinity_potency":[],"species_and_systems":"Species of experiments not reported in our evidence; database records are for human.","localisation_and_range":"Ligand annotated secreted, not transmembrane [flag].","caveats":"Three papers are pending, so no paper evidence is verified. The receptor entry lists CSF2 itself as a member of the complex, which is unusual for a receptor definition. Evidence for the individual chains is on the CSF2->CSF2RA and CSF2->CSF2RA:CSF2RB pairs.","key_references":[],"covers":["LR011699"]},"LR003887":{"pair":"CTF1 -> LIFR","headline":"CTF1 signals through a gp130/LIFR receptor; LIFR evidence is blockade in canine cells and database records.","interaction_type":"functional only","direction_and_effect":"CT-1 stimulated fibroblast growth and blockade of LIF receptor inhibited it, so CT-1 is an agonist [PMID:11834704]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"The receptor is the gp130/LIFR heterodimer; single-chain rows inherit complex-level evidence [PMID:11834704]. Reactome lists the OSM, LIF, CTF1 receptor complex binding gp130 [DB:Reactome R-HSA-6783524].","affinity_potency":[],"species_and_systems":"Cultured adult canine cardiac fibroblasts; the human and mouse pairs are ortholog-inferred [PMID:11834704].","localisation_and_range":"CTF1 flagged secreted [flag]; paracrine cytokine action on cell-surface receptor.","caveats":"Receptor blockade only, no binding; abstract only; LIFR alone not shown sufficient.","key_references":[{"PMID":"11834704","why":"LIFR blockade abolishes CT-1 growth effect in canine cells"}],"covers":["LR000381","LR003887"]},"LR003896":{"pair":"CTHRC1 -> FZD6","headline":"CTHRC1 co-precipitates with Fzd6 in HEK293 cells and modulates Wnt/PCP signalling; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Cthrc1 co-precipitated with Fzd6 in HEK293 cells, indicating interaction with multiple Fzd proteins; no binding to Smo or to C-terminally truncated Cthrc1 [PMID:18606138]. In HEK293T cells Cthrc1 activated the PCP pathway but suppressed canonical Wnt signalling [PMID:18606138].","molecular_requirements":"Cthrc1 forms a Cthrc1-Wnt-Fzd/Ror2 complex and enhances Wnt-Fzd/Ror2 interaction; it also bound Wnt3a, Wnt5a and Wnt11 [PMID:18606138]. Cthrc1 did not coprecipitate with LRP6 [PMID:18606138].","affinity_potency":[],"species_and_systems":"Co-IP in HEK293 cells; mouse knockout (Cthrc1 LacZ) and Vangl2 genetic interaction; curator labels list human species for the proteins, mouse pair ortholog-inferred [PMID:18606138].","localisation_and_range":"CTHRC1 flagged secreted [flag]; the paper describes cell-surface-anchored Cthrc1 binding [PMID:18606138].","caveats":"Co-IP shows association, not affinity or direct binding to purified protein; overexpression in cells. Single paper; Fzd paralogs bind similarly, so specificity among Fzd3/5/6 is not shown.","key_references":[{"PMID":"18606138","why":"Cthrc1 binds Fzd proteins and Ror2 and stabilizes the Wnt-receptor complex"}],"covers":["LR000390","LR003896"]},"LR005759":{"pair":"DMP1 -> CD44","headline":"Weakly supported: one abstract-only paper suggests DMP1 N-terminus interacts with CD44 in a complement-regulation context.","interaction_type":"functional only","direction_and_effect":"Overlapping fragment analysis suggests DMP1 and osteopontin interact with cell-surface CD44 through their amino termini [PMID:11825898]. CD44 serves to tether the SIBLING so that Factor H can be recruited, and complement lysis was blocked via alphaVbeta3 or CD44; output is complement regulation, not CD44 signalling [PMID:11825898].","molecular_requirements":"DMP1 N-terminal region is implicated; the effect requires Factor H and Factor I [PMID:11825898].","affinity_potency":[],"species_and_systems":"Human; described by the paper as SIBLING-expressing cells and FACS binding of Factor H [PMID:11825898].","localisation_and_range":"DMP1 annotated secreted [flag]; acts as a surface-bound anchor in this paper.","caveats":"Abstract only; no direct DMP1-CD44 binding measurement or affinity reported. The Ka of about 1 nm in the abstract refers to DMP1 and Factor H, not CD44.","key_references":[{"PMID":"11825898","why":"Fragment mapping of DMP1 to CD44"}],"covers":["LR002491","LR005759"]},"LR005768":{"pair":"Dsg1a -> Dsc2","headline":"Dsg1a -> Dsc2: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"Heterophilic trans binding between the two desmosomal cadherins: every Dsg passed over a Dsc surface, or vice versa, gave binding responses described as strong heterophilic interaction [PMID:27298358]. No directionality beyond the curator's agonist-style label is reported; the pair is best read as symmetric adhesion between cadherins on adjacent cells.","molecular_requirements":"Ectodomain-only recombinant proteins were used for SPR and bead aggregation [PMID:27298358]; no further subunits or co-receptors reported in our evidence.","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), range over all pairwise human Dsg/Dsc ectodomain combinations, not specific to this pair","system":"recombinant human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: mouse (ortholog-projected). The mouse pair is projected from human evidence; no mouse experiment is in our evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"The SPR quote was read via browser and is flagged by curators as unverifiable pending spot-check; our dossier gives only the pooled KD range, not a value for this pair. The paper's abstract was the only text in the dossier.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR005768"]},"LR007289":{"pair":"EBI3:IL12A -> IL12RB2:IL6ST","headline":"IL-35 (EBI3:IL12A) signals via IL12RB2 and gp130 chains, shown functionally in mouse T cells.","interaction_type":"functional only","direction_and_effect":"IL-35 signalled through a heterodimer of IL-12Rbeta2 and gp130, or homodimers of each chain [PMID:22306691]. UniProt for IL12A agrees [DB:UniProt].","molecular_requirements":"Cells lacking either chain were partially resistant to IL-35 suppression; loss of both gave complete resistance, and a complete receptor (both chains) was required to induce IL-35 production [PMID:22306691]. One chain suffices for partial suppression.","affinity_potency":[],"species_and_systems":"Excerpts describe mouse knockout T cells (Il12rb2-/-, Il6st deletion) and in vivo transfers [PMID:22306691]; the dossier lists human for both partners.","localisation_and_range":"Ligand is flagged as a secreted complex [flag].","caveats":"Binding was not measured in our evidence; PDB structures exist for related chains [DB:PDB 8XRP]. Read from abstract plus full-text excerpts.","key_references":[{"PMID":"22306691","why":"IL-35 receptor chain requirements"}],"covers":["LR007289"]},"LR001799":{"pair":"ECM1 -> ITGB4","headline":"One abstract-only paper reports ECM1 interacting directly with ITGB4 in gastric cancer.","interaction_type":"direct binding","direction_and_effect":"ECM1 directly interacted with ITGB4 and activated the ITGB4/FAK/GSK3beta pathway, inducing SOX2 [PMID:29059156].","molecular_requirements":"Alpha-partner of ITGB4 not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human gastric-cancer cells and xenografts; mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence beyond ECM1 being an extracellular matrix protein [PMID:29059156].","caveats":"Single paper, abstract only; the assay for direct interaction is not stated in the abstract.","key_references":[{"PMID":"29059156","why":"ECM1 interacts with ITGB4 in gastric cancer"}],"covers":["LR001799","LR005155"]},"LR003959":{"pair":"EFNA1 -> EPHA2","headline":"Ephrin-A1 is a well-supported ligand of EPHA2 with binding, structural, and cell evidence.","interaction_type":"direct binding","direction_and_effect":"Soluble EphA2-Fc bound strongly to cells expressing ephrin-A1a but only weakly to the ephrin-A1b isoform [PMID:14692877]; in mouse ESCs, EFNA1 activation of EPHA2 supports pluripotency and restrains ERK1/2 [PMID:32170114]; EphA2 is tyrosine-phosphorylated in xenograft vasculature, presumably via ephrin-A1 [PMID:11146556]. Stimulatory.","molecular_requirements":"Splice isoform matters: ephrin-A1a binds strongly, ephrin-A1b weakly [PMID:14692877]. EPHA2 pTyr in ESCs depends on EFN ligand, and RSK-driven serine/threonine phosphorylation of EPHA2 blunts the response [PMID:32170114].","affinity_potency":[{"value":"apparent KD in Fig. 1 (value not given)","assay":"ELISA, biotinylated ephrin Fc on immobilised Eph Fc","system":"not specified","cite":"PMID:22568954"}],"species_and_systems":"Human cells [PMID:14692877][PMID:11146556]; mouse ESCs, full text read [PMID:32170114]. Mouse pair is ortholog-inferred. Co-immunoprecipitation, ITC-type and structures are listed: PDB 3CZU, 3HEI, 3MBW [DB:PDB 3CZU]; BioGRID and IntAct records [DB:BioGRID][DB:IntAct].","localisation_and_range":"EFNA1 annotated secreted and transmembrane, EPHA2 transmembrane [flag]; the papers show cell-surface ligand on adjacent cells (EFNA1-expressing cells stimulating EPHA2 cells) [PMID:32170114].","caveats":"Ephrin-A1 binds EphA2 better than ephrin-A4 or ephrin-A5 in one ELISA [PMID:22568954]; no KD number is reported in the excerpt. Several papers read as abstracts only.","key_references":[{"PMID":"32170114","why":"EFNA1 activation of EPHA2 in mouse ESCs"},{"PMID":"14692877","why":"isoform-dependent EphA2-Fc binding"},{"PMID":"22568954","why":"ephrin-A1 Fc binds EphA2 best among ephrin-As"}],"covers":["LR000468","LR003959"]},"LR003968":{"pair":"EFNA2 -> EPHA3","headline":"Ephrin-A2 and EphA3 are reported as a receptor pair; one rat axon-guidance paper and a UniProt note.","interaction_type":"functional only","direction_and_effect":"Soluble ephrin-A2 and ephrin-A5 at nanomolar concentrations abolished repulsive axon-guidance activity; soluble EphA3 extracellular domain did likewise, whereas EphB3 did not [PMID:9751130]. UniProt lists EPHA3 among binders [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat retinal ganglion cell axons in vitro stripe assay [PMID:9751130].","localisation_and_range":"EFNA2 annotated transmembrane, not secreted; EPHA3 secreted and transmembrane [flag].","caveats":"The paper shows competition of repulsive activity, not direct binding; read as abstract only. Binding ligand-receptor specificity is stated as background (EphA3 is a receptor for ephrin-A2 and ephrin-A5).","key_references":[{"PMID":"9751130","why":"soluble ephrin-A2/EphA3 block axon repulsion"}],"covers":["LR000477","LR003968"]},"LR003977":{"pair":"EFNA3 -> EPHA4","headline":"Ephrin-A3 signals through EphA4 in mouse hippocampus, but binds EphA4 more weakly than other Eph receptors.","interaction_type":"direct binding","direction_and_effect":"Activation of EphA4 by ephrin-A3 induced dendritic spine retraction in adult mouse hippocampal slices; inhibiting the interaction distorted spine shape [PMID:12496762]. Ephrin-A3 binds EphA4 more weakly than other Eph receptors [PMID:22568954].","molecular_requirements":"Not reported beyond the pair; kinase-inactive EphA4 was used in slices [PMID:12496762].","affinity_potency":[],"species_and_systems":"Mouse hippocampal slices and EphA4 knockout mice [PMID:12496762]; ELISA plus pull-down from mouse hippocampus [PMID:22568954]. The human pair is ortholog-inferred.","localisation_and_range":"Both are flagged membrane-bound [flag]; ephrin-A3 is on astrocytic processes and EphA4 on spines, so signalling is glia-to-neuron contact [PMID:12496762].","caveats":"Binding strength is lower than for other Eph receptors [PMID:22568954]; that paper was a browser read with an unverifiable quote. 12496762 was read as an abstract only.","key_references":[{"PMID":"12496762","why":"Ephrin-A3 activates EphA4 to retract spines in mouse hippocampus"},{"PMID":"22568954","why":"Relative binding of ephrin-A3 to Eph receptors"}],"covers":["LR000486","LR003977"]},"LR003995":{"pair":"EFNA5 -> EPHA6","headline":"Only an IntAct coimmunoprecipitation record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"IntAct lists an association by anti-tag coimmunoprecipitation [DB:IntAct]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human and mouse pairs are ortholog-inferred.","localisation_and_range":"EFNA5 flagged membrane-bound; EPHA6 flagged membrane-bound [flag].","caveats":"All four judged papers were review-only; a single database record supports it.","key_references":[],"covers":["LR000504","LR003995"]},"LR008675":{"pair":"EFNB3 -> RHBDL2","headline":"Only a BioGRID biochemical-activity record; no curator-verified evidence.","interaction_type":"database-asserted only","direction_and_effect":"not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID record from PMID 15047175; species not given [DB:BioGRID].","localisation_and_range":"Ephrin-B3 is annotated transmembrane [flag].","caveats":"The one judged paper concerned a different entity. The BioGRID record is Biochemical Activity (a protease-substrate relationship), not ligand-receptor binding, and RHBDL2 has no receptor flags [DB:BioGRID].","key_references":[],"covers":["LR008675"]},"LR005795":{"pair":"EGFL7 -> NOTCH1","headline":"Secreted EGFL7 binds human NOTCH1 by co-IP and acts as a Notch antagonist; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Secreted EGFL7 binds a Notch region involved in ligand-mediated activation and acts as an antagonist of Notch signalling; EGFL7 expression in neural stem cells decreased Notch-specific signalling [PMID:19503073].","molecular_requirements":"Not reported in our evidence beyond Notch receptors binding EGFL7 via EGF-like domains; control receptors with EGF-like domains did not interact [PMID:19503073].","affinity_potency":[],"species_and_systems":"Endogenous human NOTCH1 co-immunoprecipitated recombinant human EGFL7 in cell lines; tagged proteins in HEK293 cells [PMID:19503073]. BioGRID lists two-hybrid and reconstituted complex records [DB:BioGRID].","localisation_and_range":"EGFL7 is secreted [flag] and the Notch receptor is transmembrane [flag]; binding was retained with the two proteins on apposing cells [PMID:19503073].","caveats":"One paper supports all three Notch paralogs, and this row has no independent confirmation. No affinity reported in our evidence.","key_references":[{"PMID":"19503073","why":"EGFL7 binds Notch1-4 and antagonises Notch signalling"}],"covers":["LR002527","LR005795"]},"LR008990":{"pair":"F2 -> GP1BB","headline":"Only a Reactome complex-level reaction supports thrombin with GP1BB; no direct evidence.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists thrombin binding to GP1b:IX:V [DB:Reactome R-HSA-429529]. Direction and effect for GP1BB alone: not reported in our evidence.","molecular_requirements":"GP1BB is only a member of the GP1b:IX:V complex in this record [DB:Reactome R-HSA-429529]; whether it binds thrombin itself is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system: not reported in our evidence (entity listed as human).","localisation_and_range":"Localisation: not reported in our evidence.","caveats":"Database assertion only; the only judged paper was a review. Likely a complex-member projection rather than a direct pair.","key_references":[],"covers":["LR008990"]},"LR008954":{"pair":"FABP5 -> RXRA","headline":"No papers; support is Reactome's intracellular complex of RXRA:PPARD:atRA:FABP5 only.","interaction_type":"database-asserted only","direction_and_effect":"Reactome describes RXRA:PPARD binding FABP5:atRA [DB:Reactome R-HSA-5422942], forming a nucleoplasm complex [DB:Reactome R-HSA-5422940]. Direction and effect: not reported in our evidence.","molecular_requirements":"RXRA binds as a heterodimer with PPARD, and FABP5 carries atRA [DB:Reactome R-HSA-5422942]; direct FABP5-RXRA binding is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Reactome pathway; no experiments in our evidence.","localisation_and_range":"Nuclear (nucleoplasm) per Reactome [DB:Reactome R-HSA-5422940]; FABP5 is an intracellular carrier, not a secreted ligand.","caveats":"Database assertion only; judged papers were abstract-insufficient or review-only. Likely not a classical extracellular ligand-receptor pair.","key_references":[],"covers":["LR008954"]},"LR005876":{"pair":"FAM3B -> FGFR1","headline":"FAM3B is reported as an FGFR ligand in one Xenopus paper; FGFR1-specific evidence is direct ectodomain binding.","interaction_type":"direct binding","direction_and_effect":"FAM3B protein bound the ectodomain of FGFR1 in solution and full-length FGFR1 in Xenopus embryos, activated ERK in HEK293T cells (blocked by four FGFR inhibitors), and drove posterior-development phenotypes in Xenopus [PMID:33975953]. A negative control, beta-Klotho ectodomain, did not bind [PMID:33975953].","molecular_requirements":"FGFR1 kinase-inactive mutant with intact ectodomain still bound FAM3B; no co-receptor requirement reported [PMID:33975953]. Whether FGFR1 acts alone: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Xenopus embryos, HEK293T cells and recombinant human FAM3B; curation row labels species human [PMID:33975953].","localisation_and_range":"FAM3B is annotated secreted [flag] and was detected in culture medium of HEK293T cells [PMID:33975953]; FGFR1 is annotated a transmembrane receptor [flag].","caveats":"Single paper. The abstract does not say which of FGFR1-4 binds; all four rows rest on a family-level claim, and the main system is Xenopus [PMID:33975953]. No affinity reported. FGF family paralog overlap is possible.","key_references":[{"PMID":"33975953","why":"FAM3B binds FGFR ectodomain and activates ERK in Xenopus/HEK293T"}],"covers":["LR002609","LR005876"]},"LR005885":{"pair":"Fcer2a -> Itgax","headline":"CD23 binds CD11c-CD18 on transfected COS cells and drives monocyte activation; human data projected to mouse.","interaction_type":"direct binding","direction_and_effect":"Recombinant CD23 in liposomes bound COS cells expressing CD11c-CD18; anti-CD11c and anti-CD23 antibodies blocked this, and CD23 triggering increased monocyte pro-inflammatory cytokines (agonist) [PMID:7621072].","molecular_requirements":"Needs the CD11c-CD18 complex; CD11a-CD18 did not bind [PMID:7621072].","affinity_potency":[],"species_and_systems":"Experiments used human CD23 and human integrins (curator fields) in COS transfectants and monocytes; the mouse pair is ortholog-inferred and no mouse experiment is in our evidence.","localisation_and_range":"Fcer2a flagged secreted and receptor [flag]; itgax flagged not secreted [flag].","caveats":"Single paper; no affinity reported.","key_references":[{"PMID":"7621072","why":"CD23 binds CD11b-CD18 and CD11c-CD18"}],"covers":["LR005885"]},"LR005894":{"pair":"FGF18 -> GLG1","headline":"Fgf18 interacts physically with Cfr (Glg1), a co-receptor that promotes Fgf18-Fgfr3c signalling; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Cfr-deficient mice resemble Fgf18-deficient mice, and Cfr and Fgf18 interact genetically and physically [PMID:20023171]. Cfr introduction facilitated Fgf18-dependent proliferation of Fgfr3c-expressing Ba/F3 cells [PMID:20023171]. Dlk binds Cfr and interrupts the Cfr-Fgf18 interaction [PMID:20023171].","molecular_requirements":"Cfr acts as a co-receptor facilitating Fgf18 signalling through Fgfr3c, not as a standalone signalling receptor [PMID:20023171]. Dlk competes with Fgf18 for Cfr.","affinity_potency":[],"species_and_systems":"Mouse knockout and Ba/F3 cell assays [PMID:20023171]; the human pair is projected from mouse (ortholog_inferred).","localisation_and_range":"GLG1 is flagged a transmembrane receptor [flag]; Fgf18 is secreted [flag].","caveats":"Single paper, abstract only; the nature of the physical assay (direct binding vs co-purification) is not detailed in the dossier. Co-receptor role means Fgfr3c expression is also needed.","key_references":[{"PMID":"20023171","why":"Cfr-Fgf18 interaction and Dlk antagonism"}],"covers":["LR002628","LR005894"]},"LR007199":{"pair":"FGF19 -> FGFR4:KLB","headline":"Complex-level pair supported only by database records; no curator-verified paper in our dossier.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists the complex FGFR4:HS:KLB:FGF19 and a reaction in which FGFR4 binds HS:KLB:FGF19 [DB:Reactome]. GtoPdb records FGF19-FGFR4 as an agonist, binding [DB:GtoPdb].","molecular_requirements":"The complex includes heparan sulfate, KLB and FGFR4 per Reactome [DB:Reactome]. PDB 6NFJ is a structure of beta-Klotho with an FGF19 C-terminal peptide, so it covers the KLB-FGF19 contact, not the whole complex [DB:PDB 6NFJ].","affinity_potency":[],"species_and_systems":"Human records only [DB:Reactome][DB:BioGRID][DB:IntAct]. Experimental system for the complex is not reported in our evidence.","localisation_and_range":"Ligand annotated secreted [flag]; membrane complex at the plasma membrane per Reactome [DB:Reactome].","caveats":"No paper was confirmed for this complex pair (one row was review only). Evidence rests on databases; the FGFR4 and KLB subunits are better supported by the separate FGF19 pairs.","key_references":[],"covers":["LR007199"]},"LR008576":{"pair":"FN1 -> ITGAV:ITGB1","headline":"AlphaVbeta1 functions as a fibronectin receptor in CHO cells; single abstract-level functional paper.","interaction_type":"functional only","direction_and_effect":"AlphaVbeta1 attaches to and spreads on fibronectin but does not support fibronectin matrix assembly or migration, unlike alpha5beta1 [PMID:8314844].","molecular_requirements":"Human alphaV combined with CHO beta1 to form alphaVbeta1 in cells lacking alpha5 [PMID:8314844].","affinity_potency":[],"species_and_systems":"Human alphaV expressed in CHO-B2 cells [PMID:8314844].","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"Only one confirmed paper (abstract-only); its quoted evidence sentence is the alpha5beta1 premise. Affinity of alphaVbeta1 cells for fibronectin was fourfold lower than alpha5beta1 cells [PMID:8314844]. Databases are mostly alpha5beta1 or alphaVbeta3 records [DB:BioGRID].","key_references":[{"PMID":"8314844","why":"alphaVbeta1 is a fibronectin receptor but not for matrix assembly"}],"covers":["LR008576"]},"LR005939":{"pair":"GDF1 -> ACVR2B","headline":"Weak functional evidence only: a GDF3 paper cites GDF1 as using ActRIIB (ACVR2B); GtoPdb asserts agonism.","interaction_type":"functional only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at this receptor [DB:GtoPdb]. The only paper states that GDF3 signalling, 'similar to GDF1', is mediated by ALK4, ActRIIA, ActRIIB and Cripto in Smad-dependent reporter assays [PMID:17936261].","molecular_requirements":"Type I ALK4, type II ActRIIA/ActRIIB and the co-receptor Cripto are named; native GDF1 was incapable of signalling in heterologous cells unless a heterologous prodomain, Furin or Nodal co-expression was used [PMID:17936261].","affinity_potency":[],"species_and_systems":"Mouse is the species with primary evidence; the human pair is ortholog-projected. The abstract does not state the cell species [PMID:17936261].","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"Abstract-only. GDF1 receptor usage is background in a paper about GDF3, not its own result [PMID:17936261]. Native GDF1 is poorly processed, so potency is not reported in our evidence.","key_references":[{"PMID":"17936261","why":"GDF3 (and, by reference, GDF1) use ALK4, ActRIIA/B and Cripto"}],"covers":["LR002674","LR005939"]},"LR005948":{"pair":"GDF3 -> ACVR1B","headline":"GDF3 signals through ALK4 (ACVR1B) in reporter assays with Cripto and type II receptors; binding itself is not shown.","interaction_type":"functional only","direction_and_effect":"GDF3 signalling can be mediated by ALK4 plus ActRIIA/ActRIIB and the co-receptor Cripto, activating Smad-dependent reporters [PMID:17936261]. Agonist [PMID:17936261][DB:GtoPdb].","molecular_requirements":"Needs type II receptors ActRIIA/ActRIIB and Cripto; native GDF3 precursor is poorly processed in heterologous cells and needs a heterologous prodomain, Furin or Nodal co-expression to signal [PMID:17936261].","affinity_potency":[],"species_and_systems":"Reporter assays in heterologous cells; curators label human ligand and receptor, though the abstract names no cell line [PMID:17936261]. The mouse pair is listed as direct and the human pair as ortholog-inferred.","localisation_and_range":"GDF3 is flagged secreted [flag]; range not reported otherwise in our evidence.","caveats":"Abstract only. No direct binding data. ALK4 effect is inseparable from type II receptors and Cripto.","key_references":[{"PMID":"17936261","why":"GDF3 signals via ALK4, ActRIIA/B and Cripto"}],"covers":["LR002683","LR005948"]},"LR005957":{"pair":"GDNF -> NCAM1","headline":"Direct binding and RET-independent signalling reported by one abstract; needs GFRA1.","interaction_type":"direct binding","direction_and_effect":"GDNF binds p140(NCAM) with high affinity, rapidly activating Fyn and FAK in RET-negative cells; it stimulates Schwann cell migration and axonal growth via NCAM and Fyn independently of RET [PMID:12837245].","molecular_requirements":"Association of NCAM with GFRalpha1 promotes high-affinity GDNF binding to p140(NCAM) and reduces NCAM-mediated adhesion [PMID:12837245].","affinity_potency":[],"species_and_systems":"Curators record human ligand and receptor; Schwann cells and hippocampal and cortical neurons were used; the human and mouse pair rows are ortholog-inferred [PMID:12837245].","localisation_and_range":"NCAM1 is a cell-adhesion molecule, giving a contact-mediated (juxtacrine) route alongside diffusible GDNF per the paper's framing [PMID:12837245]; GDNF is flagged secreted [flag].","caveats":"One paper, abstract only, no affinity value in our evidence. No database record supports the pair.","key_references":[{"PMID":"12837245","why":"NCAM as RET-independent GDNF receptor with GFRalpha1"}],"covers":["LR002692","LR005957"]},"LR007388":{"pair":"GNRH1 -> GNRHR2","headline":"Database-asserted only: Reactome records GNRHR2 binding GNRH1,2; curated papers were abstract-insufficient.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and assay of the Reactome citations not reported in our evidence [PMID:11707068][PMID:6090951][PMID:9419371].","localisation_and_range":"GnRH I is annotated as secreted and GNRHR2 as a transmembrane receptor [flag].","caveats":"No paper in our evidence supports this pair; it rests on database records alone. Two curated judgements were 'abstract_insufficient'. Reactome treats GNRH1 and GNRH2 together in one reaction, so evidence is not specific to GNRH1.","key_references":[],"covers":["LR007388"]},"LR002699":{"pair":"GPC4 -> LRRTM4","headline":"Glypicans bind LRRTM4 in a heparan-sulfate-dependent manner; GPC4 is the best-characterised glypican partner, with direct cell-free binding.","interaction_type":"direct binding","direction_and_effect":"Glypican acts as a presynaptic partner of postsynaptic LRRTM4 in a trans-synaptic interaction; the abstract calls glypican a receptor for LRRTM4. LRRTM4 positively regulates excitatory synapse development, and its synaptogenic activity requires neuronal-surface heparan sulfate [PMID:23911103].","molecular_requirements":"Binding is heparan-sulfate (HS) dependent and selective for LRRTM4 over LRRTM2 [PMID:23911103]. LRRTM4-Fc bound strongly to all glypican isoforms tested in cell-surface assays [PMID:23911103]. LRRTM4 forms separate complexes with neurexin and glypican, not a tripartite complex (GPC4 data) [PMID:23911103].","affinity_potency":[],"species_and_systems":"Rat brain homogenate pulldown, HA-tagged mouse glypican cDNAs in HEK293T cells, cultured hippocampal neurons [PMID:23911103]; the curators labelled the experiment species human. Pair is ortholog-inferred for both species.","localisation_and_range":"Glypican is a GPI-anchored HSPG (full text) and annotated as secreted [flag]; LRRTM4 is a transmembrane receptor [flag]. Interaction is trans-synaptic and needs local glypican concentration, since soluble GPC4 did not induce LRRTM4 clustering [PMID:23911103].","caveats":"This is the specifically studied member: His-LRRTM4 ectodomain co-precipitated with GPC4-Fc, confirming direct interaction, and GPC4 and LRRTM4 localise to pre- and postsynaptic membranes [PMID:23911103]. Pulldowns in 293T cells worked in both directions. Curator notes call it 'GPC1/GPC4', which is imprecise.","key_references":[{"PMID":"23911103","why":"Unbiased discovery of glypican-LRRTM4 binding and its role in synapse development"}],"covers":["LR002699","LR005964"]},"LR005966":{"pair":"GPC5 -> LRRTM4","headline":"Glypicans bind LRRTM4 in a heparan-sulfate-dependent manner; GPC5 evidence is class-level.","interaction_type":"direct binding","direction_and_effect":"Glypican acts as a presynaptic partner of postsynaptic LRRTM4 in a trans-synaptic interaction; the abstract calls glypican a receptor for LRRTM4. LRRTM4 positively regulates excitatory synapse development, and its synaptogenic activity requires neuronal-surface heparan sulfate [PMID:23911103].","molecular_requirements":"Binding is heparan-sulfate (HS) dependent and selective for LRRTM4 over LRRTM2 [PMID:23911103]. LRRTM4-Fc bound strongly to all glypican isoforms tested in cell-surface assays [PMID:23911103]. LRRTM4 forms separate complexes with neurexin and glypican, not a tripartite complex (GPC4 data) [PMID:23911103].","affinity_potency":[],"species_and_systems":"Rat brain homogenate pulldown, HA-tagged mouse glypican cDNAs in HEK293T cells, cultured hippocampal neurons [PMID:23911103]; the curators labelled the experiment species human. Pair is ortholog-inferred for both species.","localisation_and_range":"Glypican is a GPI-anchored HSPG (full text) and annotated as secreted [flag]; LRRTM4 is a transmembrane receptor [flag]. Interaction is trans-synaptic and needs local glypican concentration, since soluble GPC4 did not induce LRRTM4 clustering [PMID:23911103].","caveats":"Evidence is for 'glypican' as a class. GPC5 was detected in the LRRTM4-Fc sample but is not named in the abstract; direct cell-free binding was shown for GPC4 only [PMID:23911103].","key_references":[{"PMID":"23911103","why":"Unbiased discovery of glypican-LRRTM4 binding and its role in synapse development"}],"covers":["LR002701","LR005966"]},"LR005975":{"pair":"HBEGF -> ERBB3","headline":"HB-EGF stimulated ErbB-3-associated PI kinase activity in T47D cells; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Only NDF, HB-EGF and BTC significantly stimulated association of phosphatidylinositol kinase activity with ErbB-3 [PMID:8626392]. All EGF-related factors except amphiregulin induced ErbB-2 tyrosine phosphorylation [PMID:8626392].","molecular_requirements":"Heterodimer formation with other ErbB receptors is likely but not reported in our evidence.","affinity_potency":[],"species_and_systems":"T47D human breast tumour cells [PMID:8626392]. Mouse pair ortholog-inferred.","localisation_and_range":"Not reported in our evidence beyond flags [flag].","caveats":"Abstract only; readout is downstream, not binding.","key_references":[{"PMID":"8626392","why":"HB-EGF activates ErbB-3-linked PI kinase in T47D"}],"covers":["LR002710","LR005975"]},"LR007973":{"pair":"HFE -> TFRC","headline":"HFE and transferrin receptor 1 form a well-documented complex in databases, with a crystal structure; the papers read are indirect.","interaction_type":"direct binding","direction_and_effect":"HFE is a membrane partner that binds TFRC (TfR1) and TfR1 negatively regulates hepcidin signalling through this interaction [PMID:41662592]. Whether either is the signalling ligand or receptor is not defined in our evidence; the effect described is inhibitory, with TfR1 sequestering HFE [PMID:41662592].","molecular_requirements":"Structure with chains of Q30201 and P02786 [DB:PDB 1DE4]; Reactome lists an HFE:TFRC dimer complex and HFE binding the TFRC dimer [DB:Reactome]. In mice, liberated HFE needs Tfr2 to induce hepcidin [PMID:41662592].","affinity_potency":[],"species_and_systems":"The curated papers are a mouse hepatocyte-specific knockout study [PMID:41662592] and a computational docking and molecular dynamics study of the C282Y mutant [PMID:41277739]. Database interaction evidence includes affinity capture, reconstituted complex, surface plasmon resonance and pull-down [DB:BioGRID][DB:IntAct].","localisation_and_range":"Both entities are flagged transmembrane [flag]; contact-dependent in the plasma membrane, as in the Reactome complex [DB:Reactome].","caveats":"Papers shown are an in vivo mouse study and in silico work, not direct binding measurements; affinity not reported in our evidence. Binding evidence rests on databases.","key_references":[{"PMID":"41662592","why":"Mouse double-knockout showing Tfr1 regulates Hfe signalling"},{"PMID":"41277739","why":"Docking and MD of HFE C282Y at the TfR1 interface"}],"covers":["LR007973"]},"LR005984":{"pair":"HMGB1 -> ITGB3","headline":"HMGB1 binds soluble integrin alphavbeta3 and colocalises with beta3 on macrophages; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"HMGB1 colocalised with beta3-integrin on macrophage membranes, bound soluble alphavbeta3 but not alphavbeta5, suppressed the MFG-E8-alphavbeta3 interaction and blocked alphavbeta3-dependent uptake of apoptotic cells [PMID:20826760]. This is an inhibitory effect on efferocytosis.","molecular_requirements":"Evidence is for the alphavbeta3 heterodimer; beta3 alone was not tested separately in our evidence [PMID:20826760].","affinity_potency":[],"species_and_systems":"Macrophages and soluble integrins; species not stated in the abstract. Curated as human; the mouse pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; integrin is membrane-bound on macrophages [PMID:20826760].","caveats":"Single abstract-only paper, no affinity, and it is the same paper that supports the ITGAV pair, so the two are not independent.","key_references":[{"PMID":"20826760","why":"HMGB1 binds alphavbeta3 and colocalises with beta3"}],"covers":["LR002736","LR005984"]},"LR005993":{"pair":"HP -> TLR4","headline":"Haptoglobin is reported to act as a TLR4 ligand in osteoclast cultures; functional evidence only.","interaction_type":"functional only","direction_and_effect":"Haptoglobin stimulates IFN-beta via a TLR4-dependent mechanism, which reduces c-Fos and inhibits osteoclastogenesis; Hp-deficient mice show reduced bone volume and more osteoclasts [PMID:31076532].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Osteoclast precursor cultures and Hp-deficient mice; curated as human on both sides [PMID:31076532]. The mouse pair is ortholog-inferred.","localisation_and_range":"HP is flagged as secreted [flag].","caveats":"Abstract-only reading; no binding measurement is reported, only TLR4-dependence of the IFN-beta response.","key_references":[{"PMID":"31076532","why":"Haptoglobin induces IFN-beta via TLR4 and suppresses osteoclastogenesis"}],"covers":["LR002745","LR005993"]},"LR008567":{"pair":"HRAS -> INSR","headline":"No verified evidence; a single BioGRID biochemical-activity record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists a biochemical-activity record [DB:BioGRID]; species of the experiment is not reported in our evidence.","localisation_and_range":"HRAS carries no secreted flag; INSR is flagged as a transmembrane receptor [flag].","caveats":"No curator-verified paper: two rows judged different_entity and two abstract_insufficient. Support rests on one database record.","key_references":[],"covers":["LR008567"]},"LR008594":{"pair":"IFNL2 -> IFNLR1:IL10RB","headline":"IFN-lambda2 signals through IFNLR1:IL10RB; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"IL-28 and IL-29 interacted with a heterodimeric class II receptor of IL-10Rbeta and IL-28Ralpha [PMID:12469119]; GtoPdb lists Agonist for IFNL2-IFNLR1 and IFNL2-IL10RB [DB:GtoPdb].","molecular_requirements":"Receptor = IL-10Rbeta plus IL-28Ralpha (IFNLR1) [PMID:12469119].","affinity_potency":[],"species_and_systems":"Human, human cells [PMID:12469119].","localisation_and_range":"IFNL2 is flagged secreted and non-transmembrane; complex flagged transmembrane [flag].","caveats":"Abstract-only; the abstract speaks of IL-28 generally rather than IL-28A specifically.","key_references":[{"PMID":"12469119","why":"IL-28/IL-29 receptor discovery"}],"covers":["LR008594"]},"LR007298":{"pair":"IL17C -> IL17RA:IL17RE","headline":"IL-17C signals through IL-17RA:IL-17RE per Reactome and GtoPdb; the only curated paper supports the shared IL-17RA chain, in mice.","interaction_type":"functional only","direction_and_effect":"Agonist: GtoPdb lists IL17C with IL17RA and IL17RE as agonist [DB:GtoPdb]; Reactome lists the IL17C dimer:IL17RA:IL17RE complex at the plasma membrane [DB:Reactome]. The curated paper states IL-17RA is a shared subunit for IL-17A, IL-17C, IL-17E and IL-17F [PMID:25204502].","molecular_requirements":"Both chains are in the Reactome complex [DB:Reactome]. The paper does not name the partner chain [PMID:25204502].","affinity_potency":[],"species_and_systems":"Mouse (IL-17RA-deficient mice, LPS sepsis) [PMID:25204502].","localisation_and_range":"Receptor complex annotated as transmembrane [flag]; IL-17C annotated as secreted [flag].","caveats":"The only paper is abstract-only and shows no IL-17C binding; its experiments examined IL-17A, IL-25 and IL-17F, not IL-17C. Direct binding evidence is in the related IL-17C pairs, not this one.","key_references":[{"PMID":"25204502","why":"States IL-17RA is a shared subunit (mouse sepsis study)"}],"covers":["LR007298"]},"LR008891":{"pair":"IL18 -> IL18BP","headline":"IL-18 binds IL-18 binding protein, which inhibits IL-18; supported by database records and a crystal structure, no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Inhibitory (decoy/scavenger-like). UniProt states IL18BP isoform A binds IL-18 and inhibits its activity [DB:UniProt].","molecular_requirements":"A crystal structure of human IL-18 with human IL-18 binding protein is deposited [DB:PDB 7AL7]. BioGRID lists a reconstituted complex [DB:BioGRID]. Reactome lists the IL18BP:IL18 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human proteins in the structure [DB:PDB 7AL7]; other species not reported in our evidence.","localisation_and_range":"Reactome places the IL18BP:IL18 complex in the extracellular region [DB:Reactome]; IL-18 is annotated as secreted [flag].","caveats":"No curated paper (one review_only). Not a signalling receptor in the evidence; it is a binding protein that inhibits IL-18.","key_references":[],"covers":["LR008891"]},"LR002789":{"pair":"IL1B -> ITGA5","headline":"IL-1beta binds integrin alpha5beta1 directly according to one abstract-level paper; UniProt repeats that paper.","interaction_type":"direct binding","direction_and_effect":"IL-1beta specifically bound integrins alphavbeta3 and alpha5beta1, and the authors propose this binding is primarily important for agonistic IL-1beta signalling [PMID:29030430]. Agonist direction is the curators' label.","molecular_requirements":"The integrin heterodimer is the binding unit named in the paper (integrin alpha5beta1); this pair record is for one subunit only, and which subunit contacts IL-1beta is not reported in our evidence [PMID:29030430]. UniProt: ITGA5:ITGB1 is a receptor for IL1B and binding is essential for IL1B signaling [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human IL-1beta and human integrins in binding and signalling assays; the mouse pair is inferred from human evidence [PMID:29030430].","localisation_and_range":"IL1B is flagged secreted [flag]; the integrin is a membrane receptor, so ligand acts at the cell surface.","caveats":"Read as abstract only. The E128K mutation in the IL1R-binding site enhanced integrin binding, and Lys-to-Glu substitutions reduced but did not abolish agonistic action, so integrin binding is not the only route [PMID:29030430]. No affinity reported. UniProt support derives from the same paper.","key_references":[{"PMID":"29030430","why":"IL-1beta binds alphavbeta3 and alpha5beta1; role in agonism"}],"covers":["LR002789","LR006032"]},"LR008387":{"pair":"IL1RAP -> PTPRS","headline":"IL1RAP binds PTPRS in a human cell-surface interactome study with SPR; single paper.","interaction_type":"direct binding","direction_and_effect":"The paper states IL1RAP is known to interact with all three LAR-PTPRs, and shows SPR for the pair [PMID:32822567]. SPR sensorgrams for PTPRS-Fc binding IL1RAP-Fc are shown (analyte 2-2048 nM) [PMID:32822567]. Effect direction is not reported in our evidence.","molecular_requirements":"Ectodomain-Fc fusions were used; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ectodomain-Fc proteins, ELISA screen with SPR validation [PMID:32822567].","localisation_and_range":"Both flagged as membrane proteins [flag]; trans-synaptic LAR-PTPR interactions with IL1RAP are described [PMID:32822567].","caveats":"One primary paper; the evidence sentence cites earlier work (known interaction), so the screen result itself is only shown in a figure not in our evidence. No affinity values reported.","key_references":[{"PMID":"32822567","why":"Human IgSF interactome with SPR"}],"covers":["LR008387"]},"LR000899":{"pair":"IL24 -> IL22RA1","headline":"IL-24 uses IL22RA1 paired with IL20RB; consistent across papers, but chain-level and abstract-only.","interaction_type":"direct binding","direction_and_effect":"COS cells transfected with the IL-22R1/IL-20R2 heterodimer bind IL-24 [PMID:11706020]; mda-7 binds IL-22R plus IL-20Rbeta with STAT3 activation [PMID:11564763]; IL-24 can use IL-22R/IL-20RB [PMID:12351624]. Agonist [DB:GtoPdb].","molecular_requirements":"IL22RA1 acts with IL20RB; IL-24 can instead use IL20RA with IL20RB [PMID:11706020][DB:UniProt]. Structure with IL22RA1 chain exists [DB:PDB 6DF3].","affinity_potency":[],"species_and_systems":"Human receptors, COS and BHK cells, keratinocytes [PMID:11706020].","localisation_and_range":"IL-24 is flagged secreted [flag].","caveats":"All abstract-only; evidence is for the heterodimer, not IL22RA1 alone. One row was review_only.","key_references":[{"PMID":"11706020","why":"IL-24 binds IL-22R1/IL-20R2 transfectants"},{"PMID":"11564763","why":"IL-24 binds type II IL-20R"},{"PMID":"12351624","why":"IL-24 uses IL-22R/IL-20RB"}],"covers":["LR000899","LR004329"]},"LR002798":{"pair":"IL26 -> IL10RB","headline":"IL10RB is the broadly expressed partner chain of the IL-26 receptor; evidence is functional and the chain is shared.","interaction_type":"functional only","direction_and_effect":"IL-26 signalling through its receptor activates STAT1 and STAT3, and neutralising antibody against IL-10R2 blocks this [PMID:14764663]. Reactome has IL26:IL20RA:JAK1 binding IL10RB:TYK2 [DB:Reactome].","molecular_requirements":"IL10RB works only as a partner: the active IL-26 receptor is an IL-20R1/IL-10R2 heterodimer, and responsiveness is restricted by IL-20R1 expression because IL-10R2 is broadly expressed [PMID:14764663]. Chain-only IL10RB use is not shown.","affinity_potency":[],"species_and_systems":"Human proteins and cells [PMID:14764663].","localisation_and_range":"Not reported in our evidence beyond the complex being a receptor [flag: is_receptor].","caveats":"Read as abstract only. The paper shows blockade, not binding to IL10RB itself. Specificity for IL-26 comes from IL-20R1, and IL-10R2 is shared by other IL-10-family cytokines per the curator note [PMID:14764663]. For CCC scoring, use the IL10RB:IL20RA complex instead.","key_references":[{"PMID":"14764663","why":"IL-26 signals through IL-20R1/IL-10R2; anti-IL-10R2 blocks STAT activation."}],"covers":["LR002798"]},"LR008783":{"pair":"IL36RN -> IL36G","headline":"Ligand-ligand pair resting on PDB structures of loop-swapped IL-36Ra only; papers pending.","interaction_type":"database-asserted only","direction_and_effect":"No effect reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; X-ray structures [DB:PDB 4P0J].","localisation_and_range":"Both partners annotated secreted [flag].","caveats":"PDB entries are loop-swapped IL-36Ra [DB:PDB 4P0J][DB:PDB 4P0K]; two papers pending.","key_references":[],"covers":["LR008783"]},"LR007919":{"pair":"INHA -> ACVR1:ACVR2A","headline":"INHA on ACVR1 plus ACVR2A: database-asserted only; the type II receptor is the likely contact, no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHA with the type II receptor as agonist [DB:GtoPdb]; BioGRID has ACVR2A-INHA affinity capture-western [DB:BioGRID 275207] and Reactome has an inhibin-A:TGFBR3:ACVR2A complex [DB:Reactome]. Effect is stimulatory by annotation only.","molecular_requirements":"Type II chain ACVR2A carries the database evidence; the type I chain is not specifically evidenced in our evidence. Reactome places betaglycan (TGFBR3) in the inhibin-A:ACVR2A complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species of database experiments not reported in our evidence.","localisation_and_range":"Secreted ligand [flag]; receptor complex transmembrane [flag].","caveats":"No paper evidence supports this pair; it rests on database records. Both judged papers were review_only. GtoPdb calls INHA an agonist, whereas related papers on other INHA pairs describe inhibin as competing with activin and BMPs.","key_references":[],"covers":["LR007919"]},"LR007928":{"pair":"INHA:INHBA -> ACVR1B:ACVR2B","headline":"Inhibin-A (INHA:INHBA) to ACVR1B:ACVR2B: database support, mostly via activin A; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHA and INHBA with ACVR2B as agonist [DB:GtoPdb]. UniProt notes activin A can form a non-signalling complex with ACVR1 and a type II receptor, rendering receptors unavailable to BMPs [DB:UniProt]. Inhibin-A effect is not directly evidenced in our evidence.","molecular_requirements":"Type II chain ACVR2B binds activin A/inhibin per databases; UniProt says it binds inhibin-A/INHA-INHBA [DB:UniProt]. PDB 7OLY shows ACVR2B ligand-binding region with activin A [DB:PDB 7OLY]. Type I chain ACVR1B is not specifically evidenced.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence. X-ray structure PDB 7OLY (35005539) [DB:PDB 7OLY]; BioGRID has INHBA with ACVR2B [DB:BioGRID 282732].","localisation_and_range":"Ligand heterodimer flagged secreted [flag].","caveats":"No paper evidence supports this pair; it rests on database records. Both judged papers were review_only. The PDB structure is activin A (INHBA) with the receptor, not the INHA:INHBA heterodimer; evidence concerns INHBA rather than the inhibin heterodimer.","key_references":[],"covers":["LR007928"]},"LR000989":{"pair":"LAMA3 -> SDC2","headline":"Binding of the laminin alpha3 LG4 module to syndecan-2 shown by affinity chromatography and solid-phase assay; abstract-level read.","interaction_type":"direct binding","direction_and_effect":"Syndecan-2 from fibroblasts bound the LG4 module of laminin alpha3 by affinity chromatography, and solid-phase assays showed syndecan-2 interacting with the A3G75aR peptide (NSFMALYLSKGR) within LG4 [PMID:11373281]. Cell adhesion to LG4 depended on cell-surface heparan sulfate proteoglycans [PMID:11373281].","molecular_requirements":"The binding site is a LG4 peptide, so a LG4 fragment, not full chain, was tested; coreceptor needs not reported in our evidence.","affinity_potency":[],"species_and_systems":"Syndecan-2 from fibroblasts and recombinant fragments or peptides; species not stated in our evidence [PMID:11373281].","localisation_and_range":"LAMA3 flagged secreted; SDC2 flagged transmembrane [flag].","caveats":"Read from abstract only. BioGRID lists Affinity Capture-Western and Reconstituted Complex records from the same paper [DB:BioGRID], so these are not independent.","key_references":[{"PMID":"11373281","why":"LG4/A3G75aR binds syndecan-2"}],"covers":["LR000989","LR004408"]},"LR000998":{"pair":"LAMA5 -> ITGB4","headline":"Laminin alpha5 (as laminin-511/521) binds integrin alpha6beta4 with Kd 25 nM; a single binding paper.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant integrin alpha6beta4 [PMID:16413178]. Annotated stimulatory.","molecular_requirements":"The binder is the alpha6beta4 heterodimer; ITGB4 alone and single laminin chains were not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 25 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha6beta4)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]; mouse pair ortholog-inferred.","localisation_and_range":"LAMA5 is flagged secreted [flag] and ITGB4 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"One paper only; this is the weakest Kd among the laminin-511/521 integrin pairings in that paper (compared with 0.73 nM and 3.4 nM) [PMID:16413178].","key_references":[{"PMID":"16413178","why":"Recombinant alpha6beta4 binding to laminin-511/521"}],"covers":["LR000998","LR004417"]},"LR001001":{"pair":"LAMB1 -> ITGA7","headline":"Laminin beta1-containing laminins bind integrin alpha7beta1; recombinant Kd 0.64 nM plus melanoma and myoblast studies.","interaction_type":"direct binding","direction_and_effect":"Laminin-211/221 bound recombinant alpha7X1beta1 [PMID:16413178]. Alpha7beta1 was purified from melanoma cells by laminin affinity chromatography and binds laminin with high affinity [PMID:1839357]. Alpha7beta1 is the major laminin-binding integrin of muscle and mediates myoblast migration on laminin-1 and -2 [PMID:11278916]. Annotated stimulatory.","molecular_requirements":"Heterotrimeric laminin and the alpha7beta1 heterodimer; the alpha7 splice variants differ in laminin preference [PMID:16413178]. Individual chains such as LAMB1 were not tested alone.","affinity_potency":[{"value":"Kd 0.64 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-211/221 vs alpha7X1beta1)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]; human and murine melanoma cells [PMID:1839357]; human-labelled myoblasts and HEK293 transfection [PMID:11278916]. Mouse pair ortholog-inferred.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGA7 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Laminin-211/221 and laminin-1/-2 are tested, so LAMB1 is one of three chains. Two papers are abstract-only reads; the Kd is for the alpha7X1 variant with beta1.","key_references":[{"PMID":"16413178","why":"Kd of alpha7X1beta1 for laminin-211/221"},{"PMID":"1839357","why":"Alpha7beta1 purified from melanoma by laminin affinity"},{"PMID":"11278916","why":"Alpha7beta1 mediates myoblast migration on laminin"}],"covers":["LR001001","LR004420"]},"LR001010":{"pair":"LAMC1 -> ITGA6","headline":"LAMC1 (in laminin-511/521 and other laminins) binds integrin alpha6 at Kd 0.73 nM, with adhesion studies in platelets and cells.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant alpha6beta1 in solid-phase assays [PMID:16413178]. Platelet adhesion to purified platelet laminin was largely inhibited by antibodies to beta1 and alpha6 [PMID:10585296]. Laminar-flow assays showed alpha6beta4-positive cells attach to laminin, blocked by anti-alpha6 antibody [PMID:7699012]. Annotated effect is Stimulatory [flag].","molecular_requirements":"Ligands are assembled heterotrimers (laminin-511/521; laminin-8 in platelets; laminin LAMA1/LAMB1/LAMC1 in the flow study), so LAMC1 acts as one chain. Binder is alpha6beta1 or alpha6beta4 depending on the paper. PDB 7CEC lists chains of P11047 and P23229 [DB:PDB 7CEC].","affinity_potency":[{"value":"Kd 0.73 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha6beta1 vs laminin-511/521","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; human platelets [PMID:10585296]; cell lines of unstated species in the flow study [PMID:7699012]. Mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. The two other papers were read as abstract only and are functional (antibody blocking), not direct binding.","key_references":[{"PMID":"16413178","why":"Kd for alpha6beta1 vs laminin-511/521"},{"PMID":"10585296","why":"Platelet adhesion to laminin blocked by anti-alpha6, abstract only"},{"PMID":"7699012","why":"alpha6beta4 dynamic adhesion to laminin under flow, abstract only"}],"covers":["LR001010","LR004428"]},"LR002879":{"pair":"LGALS1 -> CD7","headline":"Galectin-1 binds T-cell glycoproteins including CD7, and CD7 is needed for galectin-1-induced T-cell death.","interaction_type":"functional only","direction_and_effect":"CD7 is required for galectin-1-mediated T-cell death, making galectin-1/CD7 a death-signalling pair; the abstract states galectin-1 binds CD7 as background [PMID:10946254].","molecular_requirements":"Galectin-1 binds several T-cell surface glycoproteins, not CD7 alone [PMID:10946254].","affinity_potency":[],"species_and_systems":"Human T cells; ligand and receptor both human [PMID:10946254]. Mouse pair ortholog-inferred. BioGRID reports Affinity Capture-Western [DB:BioGRID].","localisation_and_range":"Galectin-1 flagged secreted and receptor [flag]; acts on T-cell surface [PMID:10946254].","caveats":"Binding is cited as background, not shown by this paper; abstract-only read. Other galectin-1 receptors also contribute to death signalling.","key_references":[{"PMID":"10946254","why":"CD7 required for galectin-1-induced T-cell death"}],"covers":["LR002879","LR006113"]},"LR002888":{"pair":"LGALS3 -> MUC1","headline":"Galectin-3 binds the MUC1 extracellular domain and promotes MUC1-EGFR association; one paper, curated as direct binding but read from the abstract.","interaction_type":"direct binding","direction_and_effect":"Binding of galectin-3 to the MUC1 extracellular domain induces MUC1 cell surface polarization and increases MUC1-EGFR association, leading to increased EGFR dimerization and activation (agonist-like) [PMID:28731466].","molecular_requirements":"Requires both the galectin-3 C-terminal carbohydrate recognition domain and its N-terminal multimerization domain; the truncated galectin-3C lacking the multimerization domain had no effect [PMID:28731466].","affinity_potency":[],"species_and_systems":"Human HCT116 colon and HBL-100-derived breast epithelial cells expressing MUC1; mouse pair is ortholog-inferred [PMID:28731466].","localisation_and_range":"Both partners carry a secreted flag [flag]; galectin-3 was added exogenously to cells, so it acts as a secreted ligand on membrane MUC1.","caveats":"Binding itself was curated from the abstract (read depth abstract only); full-text passages show the functional readouts (EGFR phosphorylation) rather than a direct binding measurement. Without EGF, galectin-3 had no significant effect on EGFR activation; endogenous cell-surface galectin-3 contributed minimally [PMID:28731466]. No affinity reported.","key_references":[{"PMID":"28731466","why":"Galectin-3 binding to MUC1 promotes EGFR dimerization and activation in epithelial cancer cells"}],"covers":["LR002888","LR006122"]},"LR002897":{"pair":"LGALS8 -> ALCAM","headline":"ALCAM (CD166) was identified as a Gal-8 binding partner in vascular endothelial cells; abstract-level evidence, with proangiogenic effects of Gal-8.","interaction_type":"direct binding","direction_and_effect":"CD166/ALCAM was identified as a specific Gal-8-binding partner in normal vascular ECs; Gal-8 promoted capillary-tube formation and EC migration and induced angiogenesis in vivo in mice (agonist-like) [PMID:20876211].","molecular_requirements":"Gal-8 is a bivalent tandem-repeat galectin with two CRDs; whether ALCAM alone mediates the angiogenic effect is not reported in our evidence [PMID:20876211].","affinity_potency":[],"species_and_systems":"Human endothelial cells for binding; Matrigel plug angiogenesis in mice. Mouse pair is ortholog-inferred [PMID:20876211].","localisation_and_range":"Both partners carry secreted flags [flag]; ALCAM also a transmembrane flag [flag].","caveats":"Abstract only; the binding assay is not described and no affinity is given. The angiogenic readouts are not shown to depend on ALCAM.","key_references":[{"PMID":"20876211","why":"ALCAM identified as Gal-8 binding partner in vascular endothelial cells"}],"covers":["LR002897","LR006127"]},"LR001889":{"pair":"LGI3 -> ADAM22","headline":"LGI3 associates with ADAM22 in LPS-treated HaCaT keratinocytes; one abstract, plus Reactome records.","interaction_type":"direct binding","direction_and_effect":"Co-immunoprecipitation, flow cytometry and immunocytochemistry revealed LGI3 associated with ADAM22 in LPS-treated keratinocytes [PMID:31627033]. Reactome lists LGI3 binding ADAM22,23,syntaxin1 [DB:Reactome]. Effect direction not reported in our evidence.","molecular_requirements":"Reactome binding reaction involves ADAM22, ADAM23 and syntaxin1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"HaCaT human keratinocytes, cell-based assays [PMID:31627033]. The mouse pair is not ortholog-inferred.","localisation_and_range":"LGI3 is secreted by LPS-stimulated HaCaT cells [PMID:31627033].","caveats":"Abstract only; association by co-IP does not demonstrate direct binding. Two rows were judged different_entity.","key_references":[{"PMID":"31627033","why":"LGI3 associates with ADAM22 in keratinocytes"}],"covers":["LR001889","LR005231"]},"LR001898":{"pair":"LRRC4B -> PTPRS","headline":"NGL-3 (LRRC4B) interacts with PTPsigma via its first two FNIII domains for bidirectional synapse formation; supported by two papers and Reactome.","interaction_type":"direct binding","direction_and_effect":"PTPsigma interacts with NGL-3 via its first two FNIII domains, and this promotes synapse formation bidirectionally, like LAR [PMID:20139422]. Curators label it agonist [PMID:20139422]. PTPsigma mutants expressed on HEK293T cells bound recombinant NGL-3-Fc [PMID:29934346].","molecular_requirements":"The first two FNIII domains of PTPsigma are involved [PMID:20139422]. Three PTPsigma mutants still bound NGL-3-Fc [PMID:29934346].","affinity_potency":[],"species_and_systems":"HEK293T binding assays and rat neurons [PMID:29934346]; species of the first paper listed as human [PMID:20139422]. Reactome lists the complex [DB:Reactome]. Both listed species are ortholog-inferred.","localisation_and_range":"Membrane-bound, contact-dependent trans-synaptic adhesion (annotation [flag]).","caveats":"No affinity in our evidence. 29934346 was read via browser and the quote is marked unverifiable pending spot-check. Four other judged papers were review_only and two abstract_insufficient. Paralogs PTPRF and PTPRD bind the same ligand.","key_references":[{"PMID":"20139422","why":"NGL-3 binds PTPsigma and drives bidirectional synapse formation"},{"PMID":"29934346","why":"PTPsigma mutants bind NGL-3-Fc"}],"covers":["LR001898","LR005240"]},"LR009467":{"pair":"MDK -> GPC2","headline":"Supported only by UniProt text; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says midkine binds SDC3 or GPC2 and mediates neurite outgrowth and cell adhesion [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human annotation only; no experiment details in our evidence.","localisation_and_range":"MDK is flagged secreted, not transmembrane [flag]; receptor localisation not reported.","caveats":"The one judged paper was review_only. Cited PMIDs are in UniProt text only [PMID:12084985][PMID:1768439]. Effect direction and affinity are not reported in our evidence.","key_references":[],"covers":["LR009467"]},"LR007982":{"pair":"MMP2 -> ITGAV:ITGB3","headline":"No curated paper; only one BioGRID affinity-capture record links MMP2 to ITGB3.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. No paper rows were verified; four were judged abstract_insufficient.","molecular_requirements":"The receptor is the integrin alphaVbeta3 complex (ITGAV and ITGB3) as annotated. The BioGRID record names only MMP2 - ITGB3, so whether ITGAV is needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists an Affinity Capture-Western record (PMID 23254288); species and system are not reported in our evidence [DB:BioGRID].","localisation_and_range":"MMP2 is annotated as secreted [flag]; the complex is annotated transmembrane [flag].","caveats":"Support rests on a single database record for one chain only, with no curator-verified paper. This pair is unverified.","key_references":[],"covers":["LR007982"]},"LR002969":{"pair":"MSTN -> ACVR2A","headline":"Myostatin binds ACVR2A more weakly than ACVR2B; one binding paper plus one functional paper.","interaction_type":"direct binding","direction_and_effect":"The purified C-terminal myostatin dimer bound ActRIIB and, to a lesser extent, ActRIIA [PMID:11459935]. In human granulosa cells GDF8 suppressed PTX3 with SMAD2/3 phosphorylation; ACVR2A/ACVR2B knockdown reversed the effect [PMID:25641196].","molecular_requirements":"Type I partner ALK5 also needed in granulosa cells (knockdown reversed the effect) [PMID:25641196].","affinity_potency":[],"species_and_systems":"Purified proteins, species unspecified [PMID:11459935]; human granulosa cell lines and primary cells [PMID:25641196]; mouse pair ortholog-inferred.","localisation_and_range":"Myostatin is secreted [flag]; autocrine in follicular fluid at an average of 3 ng/ml [PMID:25641196].","caveats":"Both abstracts only. ACVR2A binding is weaker than ACVR2B; knockdown was combined for ACVR2A/ACVR2B so ACVR2A alone is not isolated.","key_references":[{"PMID":"11459935","why":"Binding to ActRIIA and ActRIIB"},{"PMID":"25641196","why":"ACVR2A/2B knockdown in granulosa cells"}],"covers":["LR002969","LR006194"]},"LR004499":{"pair":"NCAM1 -> FGFR2","headline":"Weak support: FGFR2beta/Fc bound NK-92 cells, but CD56-specific confirmation was done only for FGFR1.","interaction_type":"functional only","direction_and_effect":"FGFR2 beta/Fc chimera bound CD56-expressing NK-92 cells in flow cytometry and cell adhesion assays [PMID:12121226].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human NK-92 cells with recombinant FGFR2 beta/Fc; mouse pair is ortholog-inferred [PMID:12121226].","localisation_and_range":"NCAM flagged secreted/transmembrane [flag]; cell-surface binding on NK-92 cells [PMID:12121226].","caveats":"Abstract only. Binding is to whole cells, not to purified CD56; immunoprecipitation and the IL-2 costimulation were shown for FGFR1 only. No database records.","key_references":[{"PMID":"12121226","why":"FGFR1/FGFR2 chimeras bind NK-92 cells; CD56 confirmation for FGFR1 only"}],"covers":["LR001088","LR004499"]},"LR002978":{"pair":"NCAM1 -> SIGLEC11","headline":"PSA-NCAM is a putative Siglec-11 ligand; microglial Siglec-11 engagement was neuroprotective.","interaction_type":"functional only","direction_and_effect":"Siglec-11 cross-linking suppressed LPS-induced IL-1beta and NOS2 transcription and reduced phagocytosis of apoptotic neuronal material; curator labels it antagonist (inhibitory signalling) [PMID:20203208].","molecular_requirements":"Neuroprotection depended on polysialic acid on the neuronal side; Siglec-11 binds alpha2,8-linked polysialic acid [PMID:20203208]. The relevant form is PSA-NCAM, not unmodified NCAM.","affinity_potency":[],"species_and_systems":"Human brain tissue; human Siglec-11 variant 2 expressed in cultured murine microglia, co-cultured with neurons [PMID:20203208].","localisation_and_range":"Membrane-bound polysialylated glycoprotein contact on neurons to microglia [PMID:20203208].","caveats":"Abstract only; PSA-NCAM is called 'putative' and direct binding is not shown in the abstract. PSA may sit on other carriers. Siglec-11 is human-specific.","key_references":[{"PMID":"20203208","why":"PSA-NCAM putative Siglec-11 ligand with microglial anti-inflammatory function"}],"covers":["LR002978"]},"LR009737":{"pair":"NECTIN3 -> NECTIN2","headline":"Heterophilic nectin3/nectin2 interaction supported mainly by databases; the one confirmed paper's evidence sentence is generic.","interaction_type":"database-asserted only","direction_and_effect":"Our curator-verified paper analyses the Ig-like V domain as the dominant determinant of nectin trans-interactions across the family [PMID:12011057]; no pair-specific result is quoted. Reactome lists a Nectin-2:Nectin 3 trans heterodimer [DB:Reactome], and IntAct has surface plasmon resonance records [DB:IntAct].","molecular_requirements":"The V domain mediates nectin trans-interactions in general [PMID:12011057]; nothing pair-specific.","affinity_potency":[],"species_and_systems":"Human; recombinant ectodomains (family-wide study, abstract only) [PMID:12011057].","localisation_and_range":"Transmembrane adhesion molecules in trans at cell junctions [DB:Reactome].","caveats":"Weak paper support; one confirmed, two review-only and one abstract-insufficient. Interaction class is Receptor-Receptor.","key_references":[{"PMID":"12011057","why":"Family-wide nectin V-domain trans-interaction study"}],"covers":["LR009737"]},"LR002987":{"pair":"NFASC -> CNTNAP1","headline":"Cell aggregation with CNTN1/CASPR1 cells supports Nfasc155 binding the CNTN1:CASPR1 unit; CASPR1 alone is not tested.","interaction_type":"direct binding","direction_and_effect":"N2A cells expressing CNTN1/CASPR1 readily interact and form aggregates with Nfasc155-expressing cells; p.P705T and p.P939Ter variants abolished the interaction [PMID:31501903]. Effect direction is not reported in our evidence.","molecular_requirements":"The assay used CNTN1 together with CASPR1, so a CNTNAP1-only requirement is not shown [PMID:31501903]. Nfasc155 is the isoform tested. Reactome lists a Neurofascin:CNTN1:CASPR complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"N2A cell aggregation assay with Nfasc155 variants from human patients; species of the cells is not reported in our evidence; paper read in full text [PMID:31501903]. The human pair is listed and the mouse pair is ortholog-inferred.","localisation_and_range":"Cell-surface adhesion molecules acting through cell-cell aggregation [PMID:31501903]; neither is annotated secreted [flag].","caveats":"The paper's main finding is disease variants; the aggregation is a side assay, and the text cites an earlier report for the interaction. Chain-only evidence for CNTNAP1. Many other papers were judged abstract-insufficient or a different entity.","key_references":[{"PMID":"31501903","why":"Aggregation of Nfasc155 cells with CNTN1/CASPR1 cells, abolished by variants"}],"covers":["LR002987","LR006212"]},"LR008189":{"pair":"NID1 -> ITGAV:ITGB3","headline":"Entactin RGD binds integrin alphaVbeta3 on human mesangial cells; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Human mesangial cells use alpha v beta 3 and a beta 1-containing integrin to bind native entactin; the alpha v beta 3 site was localised to the RGD sequence in the rod/E domain [PMID:9686320].","molecular_requirements":"The complex is alphaV plus beta3; binding requires cations [PMID:9686320]. A separate beta1-integrin site exists on entactin lacking the RGD [PMID:9686320].","affinity_potency":[],"species_and_systems":"Cultured human kidney mesangial cells with wild type and mutant recombinant entactin fragments; abstract only [PMID:9686320].","localisation_and_range":"Entactin is an extracellular matrix glycoprotein; NID1 is annotated secreted [flag].","caveats":"Only one paper; authors note recombinant and native basement-membrane entactin bind differently, implying tertiary structure matters [PMID:9686320]. No database support.","key_references":[{"PMID":"9686320","why":"Mapped alpha v beta 3 binding to the RGD in entactin"}],"covers":["LR008189"]},"LR001100":{"pair":"NID1 -> PTPRF","headline":"The laminin-nidogen complex binds the LAR Fn5 domain in vitro; binding depends on a splice isoform and is of the complex, not NID1 alone.","interaction_type":"direct binding","direction_and_effect":"The laminin-nidogen complex was identified as a ligand for LAR-FnIII domain 5 in GST-fusion binding assays; antibody cross-linking of LAR inhibited cell process formation on laminin-nidogen [PMID:9647658]. Interaction is annotated stimulatory [flag].","molecular_requirements":"Binding is regulated by alternative splicing: including a small exon in LAR-Fn5 disrupts it [PMID:9647658]. The ligand was the laminin-nidogen complex, and the excerpts show binding to laminin chains [PMID:9647658].","affinity_potency":[],"species_and_systems":"GST-LAR-FnIII fusion proteins and HeLa cells; the curator records human; the paper was read in abstract and excerpts [PMID:9647658]. BioGRID records a reconstituted complex [DB:BioGRID]. Human pair is listed and mouse pair is ortholog-inferred.","localisation_and_range":"Matrix ligand; NID1 is annotated secreted [flag].","caveats":"Binding was shown for the laminin-nidogen complex; NID1 alone is not shown in our evidence. Single paper, 1998.","key_references":[{"PMID":"9647658","why":"Laminin-nidogen binds LAR-Fn5, regulated by splicing"}],"covers":["LR001100","LR004511"]},"LR008288":{"pair":"NMB -> BRS3","headline":"Thin evidence: one abstract-level chicken study suggests NMB acts on BRS3; human data are not in our evidence.","interaction_type":"functional only","direction_and_effect":"In chicken, the authors state that GRP and NMB are endogenous ligands for BRS3, from assays in CHO cells [PMID:28500250].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Chicken receptors expressed in CHO cells [PMID:28500250]; the human pair has no experiments in our evidence.","localisation_and_range":"NMB is flagged secreted [flag]; NMB is a diffusible peptide, so paracrine/endocrine action is plausible, as annotated.","caveats":"Abstract only; no potency values. Three other papers were abstract-insufficient and one was a different entity. Human relevance is extrapolated from chicken.","key_references":[{"PMID":"28500250","why":"NMB and GRP activate chicken BRS3 in CHO cells"}],"covers":["LR008288"]},"LR008558":{"pair":"NOG -> BMP7","headline":"Noggin binds BMP7 directly and inhibits it; supported by a co-crystal structure in databases, no curated paper.","interaction_type":"direct binding","direction_and_effect":"Interaction is annotated Inhibitory [flag]; PDB 1M4U is the crystal structure of BMP-7 in complex with the secreted antagonist Noggin [DB:PDB 1M4U, PMID:12478285].","molecular_requirements":"Structure has one Noggin chain and one BMP7 chain [DB:PDB 1M4U]; UniProt notes BMP7 interacts with NOG [DB:UniProt].","affinity_potency":[],"species_and_systems":"BioGRID lists co-crystal structure and reconstituted complex [DB:BioGRID, PMID:12478285]; species not reported in our evidence.","localisation_and_range":"BMP7 flagged secreted [flag]; Noggin is described as a secreted antagonist [DB:PDB 1M4U].","caveats":"No curated paper (two rated different entity, one review only); direct binding is from database structure records only. No affinity reported.","key_references":[{"PMID":"12478285","why":"Crystal structure of BMP-7 bound to Noggin"}],"covers":["LR008558"]},"LR002996":{"pair":"NPFF -> MAS1","headline":"NPFF activates MAS (MAS1) in human cell assays with an atypical calcium-led profile; one functional paper.","interaction_type":"functional only","direction_and_effect":"NPFF activated MAS with a rapid calcium rise and very weak IP1 accumulation, unlike classical Gq-PLC signalling, and weakly stimulated Galpha12/Galphai pathways; agonist [PMID:25068582].","molecular_requirements":"MAS shows strong constitutive activity; NPFF and non-peptide ligands appear to bind overlapping regions by mutagenesis [PMID:25068582].","affinity_potency":[],"species_and_systems":"Human MAS in stable inducible cells; peptides tested in calcium, IP1, cAMP and luciferase assays [PMID:25068582]. Mouse pair ortholog-inferred.","localisation_and_range":"NPFF is flagged secreted [flag].","caveats":"No binding data or EC50 in our excerpts. Angiotensin fragments only weakly potentiate at >=100 microM [PMID:25068582]. No database support.","key_references":[{"PMID":"25068582","why":"NPFF signalling and desensitization at MAS"}],"covers":["LR002996","LR006220"]},"LR009395":{"pair":"NRG2 -> ERBB2","headline":"NRG2 to ERBB2 has no verified paper evidence; only Reactome complex records.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists NRG1/2:ERBB3:ERBB2 complexes at the plasma membrane [DB:Reactome]; direction or effect of NRG2 on ERBB2 alone is not reported in our evidence.","molecular_requirements":"Reactome places ERBB2 in a complex together with ERBB3 [DB:Reactome]; direct NRG2-ERBB2 binding is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"NRG2 is flagged secreted and transmembrane [flag]; Reactome complexes are at the plasma membrane [DB:Reactome].","caveats":"Judged papers: 1 review_only, 1 different_entity, 4 abstract_insufficient; none confirmed. Reactome records are complex-level and cite PMID 24243840.","key_references":[],"covers":["LR009395"]},"LR004589":{"pair":"NXPH3 -> NRXN2","headline":"Neurexophilin-3 binds neurexin-2 LNS2 per a 2019 full-text study and a 1998 recombinant study.","interaction_type":"direct binding","direction_and_effect":"Nxph3 binding to Nrxn1-3 LNS2SS2- was tested [PMID:31566781], and neurexophilins 1 and 3 bind the second LNS domain of all three alpha-neurexins [PMID:9856994].","molecular_requirements":"LNS2 is the binding domain [PMID:9856994]. I401Q equivalents in Nrxn2 reduced Nxph1 affinity from the nanomolar to the micromolar range; the Nxph3 values are not stated in our excerpts [PMID:31566781].","affinity_potency":[],"species_and_systems":"Recombinant mouse proteins [PMID:9856994]; recombinant LNS2 constructs [PMID:31566781]. Both species pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag]; membrane neurexin [flag].","caveats":"The quoted NXPH3 sentence is the lead-in to the test, not a stated result. No affinity numbers for Nxph3 in our evidence. The 1998 paper was read as abstract only.","key_references":[{"PMID":"31566781","why":"Structures of Nxph1 with Nrxn LNS2 and isoform specificity"},{"PMID":"9856994","why":"NXPH1 and NXPH3 bind LNS2 of all three alpha-neurexins"}],"covers":["LR001180","LR004589"]},"LR004598":{"pair":"OSTN -> NPR3","headline":"OSTN binds NPR3 (NPR-C) as a competitive ligand, with a Kd of approximately 5 nM in mouse work; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Osteocrin binds specifically and saturably to NPR-C with a Kd of approximately 5 nM, with no binding to GC-A or GC-B [PMID:17951249]. It augments CNP-stimulated cGMP production, consistent with blocking NPR-C-mediated clearance, so it acts as an antagonist of NPR3 clearance [PMID:17951249]. OSTN competitively bound NPR3 with atrial NP [PMID:29326144]. GtoPdb lists OSTN as an antagonist of NPR3 [DB:GtoPdb].","molecular_requirements":"NPR3 alone is enough in the reported binding; residues important for NP binding to NPR-C are needed for Ostn binding [PMID:17951249].","affinity_potency":[{"value":"Kd approximately 5 nM","assay":"saturable binding to NPR-C","system":"mouse","cite":"PMID:17951249"}],"species_and_systems":"Mouse for Kd and transgenic work [PMID:17951249]; the second paper is labelled human but uses mouse infarct models [PMID:29326144]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"OSTN is flagged secreted [flag]; NPR3 is a flagged receptor [flag]. Secreted ligand acting by competition for clearance.","caveats":"All evidence is from abstracts. Effect is indirect: it raises NP levels rather than signalling through NPR3. A pending paper is not shown. The musclin paper [PMID:19244276] concerns musclin, a paralog name, and its species is unspecified in the dossier.","key_references":[{"PMID":"17951249","why":"Kd approximately 5 nM; NPR-C specificity"},{"PMID":"29326144","why":"Competitive NPR3 binding with atrial NP"}],"covers":["LR001189","LR004598"]},"LR009287":{"pair":"PTHLH -> RAMP2","headline":"PTHrP is not a RAMP2 ligand in the usual sense; RAMP2 modulates PTH1R responses to PTHrP, shown in functional assays.","interaction_type":"functional only","direction_and_effect":"RAMP2 enhanced PTH1R-mediated signalling responses to PTHrP (1-34) and other PTH/PTHrP ligands, whereas RAMP3 attenuated or abolished them [PMID:39376604]. RAMP2 increased PTHrP-stimulated Gas efficacy by about 150% and raised cAMP potency [PMID:39376604].","molecular_requirements":"PTH1R is required; RAMP2 acts as a modulating partner of PTH1R, and PTH1R preferentially interacted with RAMP2 by FRET [PMID:39376604]. Direct PTHrP-RAMP2 binding is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant CHO-K1 and COS-7 cells with co-expressed PTH1R and RAMP2 [PMID:39376604]; species of ligand not stated in our evidence. Human entities only.","localisation_and_range":"PTHLH is flagged as secreted [flag]; RAMP2 carries a receptor flag only [flag].","caveats":"This pair is an inference from PTH1R/RAMP2 complex pharmacology, not direct PTHrP-RAMP2 binding. Radioligand binding showed no pKd or Bmax difference between PTH1R alone and PTH1R/RAMP2 [PMID:39376604]. Abstract plus full-text excerpts only.","key_references":[{"PMID":"39376604","why":"RAMP2 modulates PTH1R signalling to PTHrP and PTH"}],"covers":["LR009287"]},"LR004679":{"pair":"PTN -> SDC3","headline":"Early affinity purification and solid-phase binding identify N-syndecan (SDC3) as a PTN (HB-GAM) receptor.","interaction_type":"direct binding","direction_and_effect":"A heparan-sulfate-bearing component isolated from perinatal rat brain on HB-GAM (PTN) affinity matrix was N-syndecan; anti-N-syndecan antibodies inhibited HB-GAM-induced neurite outgrowth (curator annotation: agonist) [PMID:8175719].","molecular_requirements":"Binding involves heparan sulfate chains on a 120-kDa core protein [PMID:8175719]; co-receptors not reported in our evidence.","affinity_potency":[{"value":"KD 0.6 nM","assay":"solid-phase binding assay","system":"N-syndecan from rat brain with HB-GAM","cite":"PMID:8175719"}],"species_and_systems":"Rat brain neurons and recombinant baculovirus HB-GAM [PMID:8175719]; dossier labels species human, which conflicts with the abstract. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"PTN is flagged secreted [flag]; SDC3 carries no localisation flag. N-syndecan was seen at neurite and cell soma surface [PMID:8175719].","caveats":"Abstract only; one confirmed paper; glycan-dependent binding; other papers were judged review-only or pending and are not shown.","key_references":[{"PMID":"8175719","why":"N-syndecan isolated as HB-GAM receptor, KD 0.6 nM"}],"covers":["LR001279","LR004679"]},"LR006389":{"pair":"PTPRS -> LRRC4B","headline":"PTPRS (PTP-sigma) binds NGL-3 (LRRC4B) through its first two FNIII domains; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"PTP-sigma interacts with NGL-3 via its first two FNIII domains, and the PTPsigma-NGL-3 interaction promotes synapse formation in a bidirectional manner [PMID:20139422]; curated direction agonist.","molecular_requirements":"PTP-sigma uses its first two FNIII domains [PMID:20139422]. Reactome lists a complex of LRRC4B with PTPRF, PTPRS and PTPRD [DB:Reactome].","affinity_potency":[],"species_and_systems":"Curated as human proteins; paper read as abstract only; both listed pairs are ortholog-inferred [PMID:20139422].","localisation_and_range":"Both flagged transmembrane (PTPRS also flagged secreted) [flag]; trans-synaptic adhesion indicates contact-dependent action [PMID:20139422].","caveats":"Only abstract-level evidence; the curated row is the reciprocal of an NGL-3 -> PTPsigma row. No affinity reported. Two further judged rows were abstract_insufficient.","key_references":[{"PMID":"20139422","why":"NGL-3 interacts with PTP-sigma via FNIII 1-2"}],"covers":["LR003168","LR006389"]},"LR006398":{"pair":"QRFP -> NPFFR2","headline":"QRFP (26RFa) binds and activates human NPFFR2 in one full-text paper, as part of an RF-amide panel; cross-reactivity, not the cognate pair.","interaction_type":"direct binding","direction_and_effect":"RF-amide peptides including 26RFa bound NPFFR in radioligand competition and activated it in [35S]GTPgammaS and cAMP assays [PMID:23911743]. In mice, effects of the RF-amide peptides were antagonised by RF9, supporting direct NPFF receptor activation [PMID:23911743].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 0.1-10 nM","assay":"radioligand competition on membranes, whole peptide panel (not QRFP alone)","system":"CHO cells expressing human receptor","cite":"PMID:23911743"}],"species_and_systems":"Human receptor in CHO membranes; in vivo pain tests in mice with peptides given i.c.v. [PMID:23911743].","localisation_and_range":"QRFP is flagged secreted [flag]; mouse effects were by central injection.","caveats":"The Ki range covers all peptides, not QRFP specifically. The paper reports GPR103 as selective for its cognate ligand, so NPFF receptors are secondary targets. Mouse pair is projected.","key_references":[{"PMID":"23911743","why":"Systematic RF-amide peptide binding and activation of NPFF1/NPFF2"}],"covers":["LR003178","LR006398"]},"LR004688":{"pair":"RBP4 -> STRA6","headline":"RBP4 and STRA6 coordinate retinol transport in adipocyte precursors; evidence here is functional plus Reactome and UniProt records.","interaction_type":"functional only","direction_and_effect":"STRA6, depending on apo- or holo-RBP4, mediates bidirectional retinol transport: retinol-loaded holo-RBP4 blocked adipocyte differentiation via RARalpha, while retinol-free apo-RBP4 triggered retinol efflux and enhanced adipogenesis [PMID:23959802]. UniProt says RBP4 transfers retinol to STRA6 [DB:UniProt].","molecular_requirements":"The effect depends on RBP4 loading state; Reactome lists complexes TTR:RBP4:STRA6 and TTR:RBP4:atROL:STRA6 [DB:Reactome R-HSA-2453850]. Ectopic STRA6 acted synergistically with apo-RBP4 [PMID:23959802].","affinity_potency":[],"species_and_systems":"Curators record human/human, but the abstract describes mouse in vivo retinoid mobilization and cultured precursor cells [PMID:23959802].","localisation_and_range":"RBP4 is flagged secreted; STRA6 is a membrane receptor [flag].","caveats":"Paper read as abstract only; no binding affinity in our evidence. The paper concerns retinol transport rather than classical signaling, and opposite outcomes arise from apo vs holo forms. The human pair is ortholog-inferred; mouse evidence is the direct data.","key_references":[{"PMID":"23959802","why":"STRA6 bidirectional retinol transport by apo/holo-RBP4"}],"covers":["LR001289","LR004688"]},"LR004697":{"pair":"RLN1 -> RXFP2","headline":"Relaxin acting through LGR8 (RXFP2) rests on one functional paper and a GtoPdb record.","interaction_type":"functional only","direction_and_effect":"LGR7 and LGR8 can mediate relaxin action via a cAMP-dependent pathway [PMID:11809971]. GtoPdb records a full agonist action [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell cAMP assays; in vivo mouse work used soluble LGR7, not RXFP2 [PMID:11809971].","localisation_and_range":"RLN1 is flagged secreted and RXFP2 transmembrane [flag].","caveats":"Five papers abstract_insufficient and one unresolvable; no binding data; the mouse in vivo result concerns LGR7, not this pair; relaxin not specified as RLN1.","key_references":[{"PMID":"11809971","why":"LGR7 and LGR8 mediate relaxin cAMP signalling"}],"covers":["LR006829","LR004697"]},"LR007991":{"pair":"RNASET2 -> TLR8","headline":"RNASET2 to TLR8 rests on a UniProt function note describing RNA degradation products sensed by TLR8; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that RNASET2 degrades microbial RNAs that are then sensed by TLR8 [DB:UniProt]. This describes an indirect, RNA-mediated route, not direct RNASET2 binding to TLR8.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated in our evidence; the pair is curated as human.","localisation_and_range":"Ligand flagged as secreted and receptor as transmembrane [flag].","caveats":"No paper confirmed the pair: two were abstract_insufficient and one was judged a different entity. Support is from UniProt only.","key_references":[],"covers":["LR007991"]},"LR006776":{"pair":"Saa3 -> Tlr4","headline":"Mouse Saa3 acts through TLR4/MD-2, but binding appears to be to MD-2 rather than TLR4; evidence is mixed.","interaction_type":"conflicting","direction_and_effect":"SAA3 synthetic peptide (20-86) stimulated migration and p38 activation dependent on TLR4, MD-2 and MyD88, and SPR gave KD values with TLR4/MD-2 protein [PMID:23858030]. However, FLAG-tagged SAA3 bound MD-2 but not TLR4, and the authors conclude SAA3 directly binds MD-2 [PMID:23858030]. Separately, bone-derived SAA3 bound TLR4 on mouse hepatocytes to phosphorylate c-Jun [PMID:38613835].","molecular_requirements":"TLR4, MD-2 and MyD88 were needed for signalling [PMID:23858030]; MD-2 may be the contact partner.","affinity_potency":[{"value":"KD 2.2 uM","assay":"SPR, SAA3 (20-86) with TLR4/MD-2","system":"baculovirus-purified protein","cite":"PMID:23858030"},{"value":"KD 30 uM","assay":"SPR, SAA3 (43-57) with TLR4/MD-2","system":"baculovirus-purified protein","cite":"PMID:23858030"}],"species_and_systems":"Mouse Saa3 and Tlr4; synthetic peptides and purified proteins, and mouse hepatocytes/in vivo [PMID:23858030][PMID:38613835].","localisation_and_range":"Secreted ligand [flag]; endocrine action from bone to liver reported [PMID:38613835].","caveats":"The 2013 paper was judged pair_absent (no direct TLR4 binding), while its abstract reports TLR4/MD-2 SPR affinities in the micromolar range. The 2024 paper is abstract only. Another paper was abstract_insufficient.","key_references":[{"PMID":"23858030","why":"SAA3 peptides: TLR4/MD-2 dependence, SPR, MD-2 binding"},{"PMID":"38613835","why":"Bone SAA3 acts via hepatocyte TLR4"}],"covers":["LR006776"]},"LR006479":{"pair":"SEMA3A -> L1CAM","headline":"L1 acts with NRP1 in Sema3A responses, but direct Sema3A-L1 binding is not shown; functional only.","interaction_type":"functional only","direction_and_effect":"Upon Sema3A binding to NP-1, L1 and NP-1 are co-internalized through a clathrin-dependent mechanism mediated by L1; an L1-mimetic peptide blocked endocytosis and growth cone collapse [PMID:15121181].","molecular_requirements":"L1 works as part of an L1/NP-1 complex; NP-1 is the Sema3A-binding subunit [PMID:15121181].","affinity_potency":[],"species_and_systems":"COS7 cells and neuronal cultures; species not specified in our evidence [PMID:15121181].","localisation_and_range":"Sema3A is flagged secreted and L1CAM membrane-bound [flag].","caveats":"Only one paper, read as abstract only. Sema3A binds NP-1, not shown to bind L1 directly, so L1 is a co-receptor rather than a demonstrated binder [PMID:15121181]. No database records.","key_references":[{"PMID":"15121181","why":"L1/NP-1 co-internalization after Sema3A"}],"covers":["LR003263","LR006479"]},"LR007397":{"pair":"SEMA3A -> NRP1:PLXNA2","headline":"A crystal structure shows Sema3A, PlxnA2 and Nrp1 in one complex; one confirmed paper.","interaction_type":"direct binding","direction_and_effect":"The structure shows a Sema3A-PlxnA2-Nrp1 complex in which Nrp1 stabilises a canonical but weakened Sema3-PlxnA interaction [PMID:23104057]. Effect is labelled agonist [PMID:23104057].","molecular_requirements":"Dimeric Sema3A, two PlxnA2 and two Nrp1 copies form a dimer of heterotrimers; Nrp1 cross-braces the assembly and is described as essential for the signaling-capable complex [PMID:23104057].","affinity_potency":[],"species_and_systems":"Mouse proteins in a low-resolution crystal structure [PMID:23104057]; curator labelled species human.","localisation_and_range":"Sema3A is flagged secreted; receptor chains membrane-bound [flag].","caveats":"Low-resolution structure, evidence read from the abstract with full-text excerpts; no affinity in our evidence. Three further rows were review-only. Database records concern Nrp-1 bound to PlexinA [DB:Reactome R-HSA-399933].","key_references":[{"PMID":"23104057","why":"Crystal structure of Sema3A-PlxnA2-Nrp1 complex"}],"covers":["LR007397"]},"LR006488":{"pair":"SEMA3F -> PLXNA2","headline":"Functional evidence only: Sema3F contracted COS-7 cells expressing NP2 with PlexA2 in one paper; mouse pair is ortholog-inferred.","interaction_type":"functional only","direction_and_effect":"In COS-7 cells expressing NP2 plus PlexA1 or PlexA2, Sema3F caused contraction, whereas Sema3A and Sema3C did not [PMID:11239433]. This is a signalling readout, not binding.","molecular_requirements":"NP2 co-expression was part of the assay, so PlexA2 acts with NP2 [PMID:11239433]. Whether PlexA2 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"COS-7 cell contraction assay, full text read; species not specified for the experiment [PMID:11239433]. Both listed pairs are ortholog-inferred.","localisation_and_range":"Not reported in our evidence beyond SEMA3F being flagged secreted [flag].","caveats":"Single paper; no direct binding or affinity reported. Interaction rests on co-expression of NP2.","key_references":[{"PMID":"11239433","why":"COS-7 contraction by Sema3F with NP2/PlexA1 or PlexA2"}],"covers":["LR003272","LR006488"]},"LR006497":{"pair":"SEMA5A -> PLXNA2","headline":"Supported by one full-text mouse study showing Sema5A-Fc binding to hippocampal neurons that depends on PlexinA2 and a functional requirement in granule cells.","interaction_type":"direct binding","direction_and_effect":"Sema5A-Fc binding was greatly reduced in Plxna2-/- hippocampal neurons and virtually absent in Plxna1-/-;Plxna2 double mutants [PMID:25313870]. Plxna2-/- GCs had increased spine density (1.94 \u00b1 0.04 vs WT 1.47 \u00b1 0.05 spines/\u00b5m in culture), similar to Sema5A-/- GCs (2.23 \u00b1 0.08), so Sema5A acts through PlexA2 to suppress spines [PMID:25313870].","molecular_requirements":"Binding was also reduced in Plxna1-/- neurons, so PlexA1 may contribute to binding; a Plxna3 knockout did not reduce it [PMID:25313870].","affinity_potency":[],"species_and_systems":"Mouse neurons and mice (ligand and receptor both mouse). Human and mouse pairs in the dossier are both ortholog-inferred.","localisation_and_range":"Ligand is flagged membrane-bound, not secreted [flag]; the paper discusses signalling in cis or in trans [PMID:25313870].","caveats":"Single paper only; binding was measured on neurons by loss of binding, not with purified proteins, and no affinity is reported.","key_references":[{"PMID":"25313870","why":"Sema5A-Fc binding and spine-density genetics with PlexA2"}],"covers":["LR003281","LR006497"]},"LR004769":{"pair":"SERPINE1 -> LRP1","headline":"PAI-1 and its uPA complexes bind LRP1; complexes bind about 100-fold tighter, and PAI-1 drives LRP1-dependent migration signalling.","interaction_type":"direct binding","direction_and_effect":"uPA:PAI-1 complexes bind LRP1 with about 100-fold increased affinity over PAI-1 alone [PMID:31792055]. Both active and cleaved PAI-1 activate Jak/Stat and stimulate migration; anti-LRP antibodies and RAP block this, and PAI-1 had no chemotactic effect on LRP-deficient cells [PMID:15001579]. Thrombin-PAI-1 endocytosis was blocked by LRP antibodies and RAP [PMID:8626514].","molecular_requirements":"Lysines 80, 88 and 207 of PAI-1 are implicated, with a bivalent binding model, and uPA:PAI-1 complex binds through three regions to LDLa repeats [PMID:31792055]. Motogenic action needs an LRP-binding PAI-1 but not protease-inhibitory activity [PMID:15001579]. In the myogenic-cell paper, LRP acts on the assembled [uPAR:uPA:PAI-1] complex [PMID:10896774].","affinity_potency":[],"species_and_systems":"Human proteins as labelled; surface plasmon resonance with recombinant proteins [PMID:31792055]; pneumocytes and migration assays [PMID:8626514, PMID:15001579]; human myogenic cells [PMID:10896774]. Mouse pair is ortholog-projected. BioGRID lists an affinity-capture-western record [DB:BioGRID].","localisation_and_range":"Both clearance (endocytic) and signalling roles are reported [PMID:8626514, PMID:15001579]; secreted and matrix PAI-1 is not annotated beyond the secreted flag [flag].","caveats":"All four papers abstract only. Free PAI-1 binding was described in the literature as controversial [PMID:31792055]. One functional paper concerns the whole complex and has no binding measurement [PMID:10896774]. UniProt describes LRP1 binding to tPA alone or with SERPINE1 [DB:UniProt].","key_references":[{"PMID":"31792055","why":"Mutational and SPR mapping of PAI-1 and uPA:PAI-1 binding to LRP1"},{"PMID":"15001579","why":"LRP1-dependent motogenic signalling by PAI-1"},{"PMID":"8626514","why":"LRP-mediated thrombin-PAI-1 endocytosis"}],"covers":["LR001374","LR004769"]},"LR004778":{"pair":"SFTPD -> LY96","headline":"SP-D binds soluble MD-2 directly via its CRD, confirmed by several assays; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"The curator labels the effect agonist, but our evidence only shows binding; functional effect on signalling is not reported in our evidence [PMID:18991397].","molecular_requirements":"Binding is concentration- and Ca2+-dependent, localised to the carbohydrate recognition domain, and independent of MD-2 N-glycosylation [PMID:18991397]. Reactome lists the TLR4:LY96 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Soluble recombinant human MD-2 and SP-D (microtiter-well, co-sedimentation, BIAcore, pulldown); mouse pair is ortholog-inferred [PMID:18991397].","localisation_and_range":"SP-D is flagged secreted [flag].","caveats":"One paper, abstract only; no affinity values reported.","key_references":[{"PMID":"18991397","why":"SP-D binds MD-2 through the CRD"}],"covers":["LR001383","LR004778"]},"LR004787":{"pair":"SLIT1 -> GPC1","headline":"One abstract-only rat-brain affinity purification supports SLIT1 binding glypican-1; heparan sulfate dependent.","interaction_type":"direct binding","direction_and_effect":"Glypican-1-Fc affinity chromatography of rat brain extract recovered Slit-1 and Slit-2 peptide sequences in a 200-kDa band [PMID:10364234]. Signalling effect is not reported in our evidence.","molecular_requirements":"Binding requires the heparan sulfate chains on glypican [PMID:10364234].","affinity_potency":[],"species_and_systems":"Rat brain extract and recombinant glypican-1-Fc from 293 cells [PMID:10364234]. Human and mouse rows are ortholog-inferred or not shown.","localisation_and_range":"SLIT1 is flagged secreted and GPC1 secreted/receptor [flag]; a heparan sulfate proteoglycan interaction.","caveats":"Abstract only; one paper, no affinity. Slit-1 and Slit-2 were isolated together, and one further row is pending.","key_references":[{"PMID":"10364234","why":"Slits isolated on glypican-1-Fc, heparan sulfate dependent"}],"covers":["LR001392","LR004787"]},"LR001988":{"pair":"SLITRK1 -> PTPRD","headline":"SLITRK1 and PTPdelta show cell aggregation and a co-crystal structure record; family-level evidence.","interaction_type":"direct binding","direction_and_effect":"Slitrk1-, Slitrk2- or Slitrk3-expressing L cells aggregated with PTPdelta-expressing L cells [PMID:23345436]. PTPdelta was needed for inhibitory synapse differentiation by Slitrks [PMID:23345436].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse L cells and rat neurons [PMID:23345436]. Mouse pair ortholog-inferred.","localisation_and_range":"Both partners are transmembrane [flag]; trans-synaptic contact (cell-adhesion assay) [PMID:23345436].","caveats":"The paper's evidence is a family-level aggregation assay (browser-read, spot-check pending), not SLITRK1-specific binding. Database records: BioGRID co-crystal structure and reconstituted complex [DB:BioGRID], PDB 4RCA [DB:PDB 4RCA]. Four review-only rows not shown.","key_references":[{"PMID":"23345436","why":"Slitrk1 L-cell aggregation with PTPdelta"}],"covers":["LR001988","LR005317"]},"LR001997":{"pair":"SLPI -> PLSCR4","headline":"SLPI binds PLSCR4 in a pull-down from transfected cells; evidence is a single paper and less detailed than for PLSCR1.","interaction_type":"direct binding","direction_and_effect":"The paper calls SLPI a ligand of PLSCR1 and PLSCR4 and the curated effect is antagonist; the competition with CD4 was tested on PLSCR1 [PMID:19333378].","molecular_requirements":"GFP-PLSCR4, but not GFP-PLSCR3, was pulled down on GST-SLPI beads [PMID:19333378]. Domain mapping was done for PLSCR1 only; not reported for PLSCR4 in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins expressed as GFP fusions in transfected cells with Jurkat T cells [PMID:19333378]. Mouse pair is projected from human evidence.","localisation_and_range":"SLPI is flagged secreted [flag]. PLSCR4 was found primarily at the plasma membrane of T cells and the authors state SLPI must cross the membrane to bind its endofacial domain [PMID:19333378].","caveats":"Curator read abstract level only. The mapped binding region and the CD4 competition are described for PLSCR1, so the curated notes on PLSCR4 competition go beyond what the excerpts show. Direct (purified) binding is shown for PLSCR1; for PLSCR4 only the pull-down is shown in our excerpts [PMID:19333378].","key_references":[{"PMID":"19333378","why":"Pull-down showing SLPI binds PLSCR1 and PLSCR4 but not PLSCR3"}],"covers":["LR001997","LR005326"]},"LR002000":{"pair":"SOST -> LRP4","headline":"Sclerostin binds Lrp4 in cell-free and cell-based pulldowns; Lrp4-deficient mice show bone defects.","interaction_type":"direct binding","direction_and_effect":"Sclerostin binds Lrp4 in vitro by pulldown and a cell-free assay with Lrp4 ectodomain-Fc [PMID:19936252]. Lrp4-deficient mice have reduced bone mass and density and raised turnover markers; Lrp4 may be an additional regulatory node beyond Lrp5/6, per the curator note [PMID:19936252]. The effect on signalling through Lrp4 is not shown in our evidence.","molecular_requirements":"Lrp4 ectodomain is sufficient for binding in the cell-free assay [PMID:19936252]. Other co-receptors are not reported.","affinity_potency":[],"species_and_systems":"HEK293A cells overexpressing Lrp4 and a cell-free assay; knockout mice for bone phenotype [PMID:19936252]. Human and mouse pairs are both ortholog-inferred. IntAct lists ELISA and SPR records from PMID 21471202 [DB:IntAct].","localisation_and_range":"SOST is flagged secreted and LRP4 as a receptor [flag]. Sclerostin is described as an osteocyte-secreted protein acting on osteoblasts [PMID:19936252].","caveats":"Paper read as abstract and excerpts. No affinity in the paper excerpts. The genetic phenotype is not specific to sclerostin binding. Both pairs are ortholog-inferred.","key_references":[{"PMID":"19936252","why":"Lrp4 binds Dkk1 and sclerostin; Lrp4 mutant bone phenotype"}],"covers":["LR002000","LR005328"]},"LR004796":{"pair":"SPINK1 -> EGFR","headline":"SPINK1 binds EGFR and weakly activates it in prostate cancer models; one paper with full-text excerpts.","interaction_type":"direct binding","direction_and_effect":"Recombinant SPINK1 induced EGFR phosphorylation in 22RV1 cells, weaker than EGF; EGFR knockdown or cetuximab reduced SPINK1 effects, so SPINK1 partially mediates neoplastic effects through EGFR [PMID:21368222]. Partial agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human: SPINK1-GST pulled down EGFR from EGFR-overexpressing HEK293 lysates and from endogenous EGFR in 22RV1 cells; endogenous SPINK1-EGFR co-immunoprecipitation was not detected [PMID:21368222]. Xenografts in mice. Mouse pair ortholog-inferred.","localisation_and_range":"SPINK1 is flagged secreted [flag]; acts on cell-surface EGFR.","caveats":"Only some, not all, SPINK1 effects are EGFR-dependent [PMID:21368222]. One further paper was review_only. No affinity.","key_references":[{"PMID":"21368222","why":"SPINK1 interacts with EGFR and induces its phosphorylation"}],"covers":["LR001401","LR004796"]},"LR006569":{"pair":"TGFB1 -> CDCP1","headline":"CDCP1 CUB domains bind TGF-beta1 directly by SPR and enhance TGF-beta1 signalling; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CDCP1 CUB domains bind directly to TGF-beta1 and BMP4 on a BIAcore chip; CDCP1 enhances TGF-beta1 reporter activity and phospho-Smad2, proposed as a co-receptor [PMID:31302030].","molecular_requirements":"CUB domains mediate binding; the effect on Smad2 depends on Smad2 and TGFRI and not on Src or PKC-delta binding [PMID:31302030].","affinity_potency":[],"species_and_systems":"Human proteins (SPR) [PMID:31302030]; mouse pair is ortholog-inferred.","localisation_and_range":"TGFB1 is flagged secreted [flag]. CDCP1 is described as a transmembrane glycoprotein, although the entity is also flagged secreted [flag] [PMID:31302030].","caveats":"Abstract read only; no affinity reported. CDCP1 is described as a co-receptor enhancing signalling, not a standalone signalling receptor. Also binds BMP4 but does not modulate BMP signalling [PMID:31302030].","key_references":[{"PMID":"31302030","why":"SPR binding of CDCP1 CUB domains to TGF-beta1"}],"covers":["LR003368","LR006569"]},"LR008279":{"pair":"TGFB2 -> ACVR1:TGFBR1","headline":"Complex row ACVR1:TGFBR1 for TGF-beta2 with no verified paper; only database text about TGFBR1/TGFBR2.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists TGFB2-TGFBR1 as agonist [DB:GtoPdb]. UniProt describes TGFB2 acting through TGFBR1 and TGFBR2 [DB:UniProt].","molecular_requirements":"The records name TGFBR1 with TGFBR2, not ACVR1; a TGFBR1:ACVR1 receptor requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experiments in our evidence; human complex.","localisation_and_range":"Ligand secreted [flag].","caveats":"No curator-verified paper; one paper judged abstract-insufficient. Treat as unsupported for ACVR1.","key_references":[],"covers":["LR008279"]},"LR006578":{"pair":"TGFBI -> STAB2","headline":"One paper reports TGFBI as a circulating ligand of STAB2 by pulldown and endocytosis; single-paper, abstract-level support.","interaction_type":"direct binding","direction_and_effect":"TGFBi was independently confirmed as a novel circulating ligand of Stab1/2 [PMID:36325910]. Clearance by the stabilins suppresses monocyte activation in this paper's model [PMID:36325910].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Ligand binding used GST-pulldown and endocytosis assays; the atherosclerosis work used mice [PMID:36325910]. Which species the binding assays used is not stated in the abstract.","localisation_and_range":"TGFBI is flagged secreted [flag]; the paper describes circulating plasma ligands cleared by liver sinusoidal endothelial cells [PMID:36325910].","caveats":"Only one paper, read as abstract only; the abstract does not detail the binding result for this specific pair. Stab1 and Stab2 are paralogs, with the same claim made for both.","key_references":[{"PMID":"36325910","why":"Stab1/2 scavenger receptor ligands including TGFBi"}],"covers":["LR003377","LR006578"]},"LR004859":{"pair":"THBS1 -> ITGA2B","headline":"Weak platelet GPIIb-IIIa binding to THBS1 plus a CD47-dependent activation route; evidence is older and abstract-level.","interaction_type":"direct binding","direction_and_effect":"GPIIb-IIIa (alphaIIbbeta3) from human platelets bound a thrombospondin column and was eluted with GRGDSP peptide, but it bound 'relatively weakly' [PMID:2478219]. Separately, THBS1 activates alphaIIbbeta3 through CD47 (agonist), as a secreted costimulator [PMID:9169439]. Reactome records the alphaIIbbeta3:THBS1 interaction [DB:Reactome].","molecular_requirements":"The beta3 chain partners ITGA2B in this binding [PMID:2478219]. The activation route requires CD47 engagement, with alphaIIb, beta3 and c-Src co-precipitating with CD47 [PMID:9169439].","affinity_potency":[],"species_and_systems":"Human platelet membrane proteins for binding [PMID:2478219]; the activation paper is recorded as mouse in this row, though its abstract does not name a species [PMID:9169439].","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"Both papers read as abstracts. The 1997 paper shows indirect activation via CD47 rather than direct alphaIIbbeta3 binding. One further paper was judged abstract-insufficient. No affinity reported.","key_references":[{"PMID":"2478219","why":"THBS1-Sepharose retains platelet GPIIb-IIIa, eluted by RGD peptide"},{"PMID":"9169439","why":"THBS1 activates alphaIIbbeta3 via CD47"}],"covers":["LR001464","LR004859"]},"LR006587":{"pair":"THBS2 -> CD36","headline":"The N-terminal fragment of THBS2 acts via CD36 to inhibit tube formation and induce apoptosis in endothelial cells; full-length protein not tested.","interaction_type":"functional only","direction_and_effect":"N-TSP2-Fc inhibits VEGF-induced tube formation of HDMEC and induces apoptosis in a CD36-dependent manner; a blocking anti-CD36 antibody abolished the effect [PMID:20714802]. Antiangiogenic, receptor-dependent.","molecular_requirements":"Only the N-terminal region fused to IgG-Fc1 was tested; other subunits not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human dermal microvascular endothelial cells in vitro and human breast tumour xenografts in mice [PMID:20714802].","localisation_and_range":"THBS2 flagged secreted [flag].","caveats":"Fragment-specific, not full-length THBS2; abstract plus some full text; no binding measured, CD36 dependence rests on antibody blockade.","key_references":[{"PMID":"20714802","why":"N-TSP2-Fc antiangiogenic activity depends on CD36"}],"covers":["LR003386","LR006587"]},"LR006596":{"pair":"THY1 -> ITGAX","headline":"The alphaX I-domain of CD11c/CD18 binds Thy-1 directly; single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Direction/effect not reported in our evidence beyond specific binding [PMID:15850796].","molecular_requirements":"The I-domain of alphaX-beta2 alone bound Thy-1 in a divalent-cation-dependent manner; D249 and KE243/244 on the betaD-alpha5 loop mutants lowered affinity [PMID:15850796].","affinity_potency":[{"value":"KD 1.16muM","assay":"alphaX I-domain binding to Thy-1","system":"purified I-domain","cite":"PMID:15850796"}],"species_and_systems":"Recombinant protein binding; species not stated in the dossier for this row [PMID:15850796].","localisation_and_range":"Both membrane proteins [flag]; contact-dependent.","caveats":"Abstract only; evidence is for an isolated I-domain rather than full integrin. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"15850796","why":"alphaX I-domain binds Thy-1, KD 1.16muM"}],"covers":["LR003395","LR006596"]},"LR004886":{"pair":"TNC -> PTPRZ1","headline":"Direct binding of tenascin-C to the PTPRZ1 ectodomain is supported by structural and binding work, mostly in recombinant and mouse systems; one paper is abstract-only.","interaction_type":"direct binding","direction_and_effect":"Tenascin-C is the ligand and PTPRZ1 (RPTP-zeta) the receptor. RPTP-zeta forms a complex with tenascin-C that is structurally the same as its complex with tenascin-R [PMID:37356715]. A soluble RPTPbeta FNIII fragment blocked adhesion and spreading of astrocytoma cells on tenascin C, so the binding is functional in adhesion [PMID:11313993]. Signalling direction (agonist or inhibitor) is not reported in our evidence.","molecular_requirements":"The C-terminal fibrinogen-like (Fg) region (FN1-Fg) of tenascin-C bound RPTP-zeta, and binding mapped to the single FN repeat of the RPTP-zeta ectodomain; it did not bind the homolog RPTP-gamma [PMID:37356715]. An earlier study mapped binding to alternatively spliced repeats A1,2,4 [PMID:11313993]. Only one chain per partner is described.","affinity_potency":[],"species_and_systems":"Full-text work used human tenascin-C fusion proteins on HEK293 cells expressing RPTP-zeta, plus structural analysis in a mouse perineuronal-net context [PMID:37356715]. The adhesion study used human glial tumour cells [PMID:11313993]. A PDB record of the two proteins exists [DB:PDB 8FN8].","localisation_and_range":"Tenascin-C is flagged secreted and PTPRZ1 flagged secreted and transmembrane [flag]. Tenascin-C is described as an extracellular matrix protein, so signalling is likely juxtacrine or matrix-contact [PMID:37356715].","caveats":"The first structural paper was read as abstract plus excerpts only. One confirming paper is an expression-profiling study that calls tenascin-C a high-affinity ligand as background and did not test binding itself [PMID:20689858]. The adhesion paper uses the name 'RPTPbeta', which may be ambiguous with PTPRB, and it was read as abstract only [PMID:11313993].","key_references":[{"PMID":"37356715","why":"Binding and structure of PTPRZ1 ectodomain with tenascin-C, FN1-Fg domains"},{"PMID":"11313993","why":"RPTPbeta FNIII binds tenascin C and mediates glial tumour cell adhesion"}],"covers":["LR001491","LR004886"]},"LR004895":{"pair":"TNFSF13 -> TNFRSF1A","headline":"No supporting paper; the curated paper does not mention TNFR1, leaving only a BioGRID record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"APRIL flagged secreted, TNFRSF1A transmembrane [flag].","caveats":"The curated paper (abstract only) reported coprecipitation of Fas and HVEM only; TNFR1 is not named as a partner, so the verified outcome is pair_absent [PMID:10706119]. The BioGRID record cites that same paper [DB:BioGRID]. Likely a mis-attribution.","key_references":[],"covers":["LR001505","LR004895"]},"LR004949":{"pair":"VTN -> ITGAV","headline":"Vitronectin engages alphaV integrins, but specificity depends on the beta partner; several papers, mostly abstract-only.","interaction_type":"direct binding","direction_and_effect":"Purified alphaVbeta5 bound preferentially to vitronectin while alphaVbeta3 bound vitronectin, fibrinogen, von Willebrand factor and fibronectin [PMID:1694173]. In hESCs, integrin-blocking antibodies showed alphaVbeta5 mediates adhesion to vitronectin [PMID:18599809], and ITGAV knockdown disrupted vitronectin-promoted endoderm differentiation [PMID:23154389]. A VTN(381-397) fragment bound only alphaVbeta6 and prevented TGF-beta1 activation (antagonist) [PMID:33526813].","molecular_requirements":"The beta chain determines specificity: alphaVbeta5 binds vitronectin but alphaVbeta6 bound fibronectin and not vitronectin in FG-2 cell lysates [PMID:1532572]; in neuroblastoma extracts vitronectin binding was mediated by alphaVbeta3, not an alphaV-beta-n complex [PMID:1693626]. ITGAV alone is not shown to suffice.","affinity_potency":[{"value":"IC50 = 3.2 \u00b5M","assay":"competition with radiolabelled echistatin for VTN(381-397) peptide","system":"recombinant human alphaVbeta6","cite":"PMID:33526813"}],"species_and_systems":"Human ligands and receptors throughout: purified placental protein, tumour cell lysates, hESCs [PMID:1694173] [PMID:18599809] [PMID:23154389]. Mouse pair is ortholog-inferred.","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Gene-level ITGAV row is only valid through specific heterodimers, not alphaVbeta6 for full vitronectin [PMID:1532572]. Most papers were read as abstract only. The antagonist effect at alphaVbeta6 is for a fragment, not full-length vitronectin [PMID:33526813]. hESC papers are functional, not binding [PMID:18599809] [PMID:23154389].","key_references":[{"PMID":"1694173","why":"Purified alphaVbeta5 as a vitronectin-selective receptor"},{"PMID":"33526813","why":"VTN fragment binds alphaVbeta6 (IC50 = 3.2 \u00b5M) and antagonises TGF-beta1 activation"},{"PMID":"23154389","why":"ITGAV knockdown impairs vitronectin-promoted endoderm differentiation in hESCs"}],"covers":["LR001560","LR004949"]},"LR004958":{"pair":"VWF -> ITGA2B","headline":"VWF binds platelet GPIIb/IIIa (alphaIIb) via RGDS and C4 domain; evidence from two abstract-only papers, chain-level.","interaction_type":"functional only","direction_and_effect":"RGDS point mutants of recombinant vWF could not displace 125I-vWF from thrombin- or ADP-activated platelets, so the RGDS site is needed for GPIIb/IIIa binding [PMID:1737795]. A cell-based assay with HEK293 cells expressing constitutively active GPIIb/IIIa measured binding of 14 VWF C domain mutants; four showed significantly reduced binding [PMID:31035301]. Curated effect is stimulatory.","molecular_requirements":"The receptor is the alphaIIb-beta3 complex (GPIIb/IIIa), activated by inside-out signalling [PMID:31035301]; VWF binds through RGDS and its C4 domain.","affinity_potency":[],"species_and_systems":"Human proteins; CHO-produced recombinant vWF with platelets and HUVEC, and HEK293 cells [PMID:1737795] [PMID:31035301]. Reactome and IntAct list the alphaIIbbeta3:VWF interaction [DB:Reactome] [DB:IntAct]. Mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence.","caveats":"Both papers are abstract-only. Evidence is for the GPIIb/IIIa complex, not alphaIIb alone, and the first paper infers the receptor from platelet binding. No affinity reported.","key_references":[{"PMID":"1737795","why":"RGDS mutations impair vWF binding to activated platelets"},{"PMID":"31035301","why":"cell-based GPIIb/IIIa binding assay for VWF C domain variants"}],"covers":["LR001569","LR004958"]},"LR006659":{"pair":"VWF -> STAB2","headline":"Stabilin-2 binds and internalises VWF and mediates VWF-FVIII clearance; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Stabilin-2-expressing cells bind and internalise human VWF and FVIII in a VWF-dependent manner, and stabilin-2-deficient mice had prolonged human VWF-FVIII half-life [PMID:30124466]. Variant p.E2377K decreased stabilin-2 expression and impaired VWF endocytosis. Acts as a clearance receptor.","molecular_requirements":"Binding was VWF-dependent for FVIII uptake [PMID:30124466]; further requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human VWF with mouse in vivo and heterologous cell expression [PMID:30124466]. Both pairs are listed, mouse not ortholog-inferred.","localisation_and_range":"Endothelial scavenger receptor [PMID:30124466].","caveats":"Abstract-only read. The curated binding label comes from cell uptake, not purified binding. No affinity reported.","key_references":[{"PMID":"30124466","why":"stabilin-2 clears VWF-FVIII"}],"covers":["LR003459","LR006659"]},"LR004967":{"pair":"WNT1 -> LRP6","headline":"WNT1 binds the LRP6 ectodomain; two abstract-level papers plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"The LRP6 extracellular domain bound Wnt-1 and associated with Fz in a Wnt-dependent manner; LRP6 acted as a Wnt co-receptor [PMID:11029007]. Anti-LRP6 antibodies defined Wnt1-class proteins as engaging the first propeller domain [PMID:20713706].","molecular_requirements":"Wnt1-class proteins use LRP6's first propeller, distinct from Wnt3a-class proteins (third propeller) [PMID:20713706]. Fz association was Wnt-dependent [PMID:11029007].","affinity_potency":[],"species_and_systems":"Xenopus embryos and ectodomain binding [PMID:11029007]; phage-display antibodies and MMTV-Wnt1 xenografts [PMID:20713706]. Both abstract only. Curators record human species; the abstracts do not state it.","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"Propeller assignment is inferred from antibody epitope mapping, not direct Wnt1 mapping. BioGRID lists a reconstituted complex [DB:BioGRID]. Four papers were abstract_insufficient.","key_references":[{"PMID":"11029007","why":"LRP6 ectodomain binds Wnt-1"},{"PMID":"20713706","why":"Wnt1 uses LRP6 first propeller"}],"covers":["LR001578","LR004967"]},"LR007469":{"pair":"WNT1 -> SFRP1","headline":"Database-asserted only: BioGRID lists a WNT1-SFRP1 affinity capture; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID records WNT1-SFRP1 by affinity capture-western [DB:BioGRID]. The interaction is annotated inhibitory; the mechanism (for example decoy) is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system of the BioGRID record are not reported in our evidence.","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"One judged paper was review_only; no verified primary paper.","key_references":[],"covers":["LR007469"]},"LR010997":{"pair":"WNT10B -> FZD4:LRP5","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54924173].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Two curation rows are still pending; no paper has been judged.","key_references":[],"covers":["LR010997"]},"LR006668":{"pair":"WNT10B -> FZD6","headline":"Several human-cell studies support WNT10B acting on FZD6, mostly functional; one co-IP shows association in HEK293T.","interaction_type":"functional only","direction_and_effect":"Recombinant WNT-10B (among other WNTs) increased FZD6-GFP mobile fraction in FRAP, an agonist-type effect [PMID:24873871]. In co-culture IP, FZD6 co-precipitated Wnt10b, and SMOC-2 enhanced the Wnt10b-Fzd6 binding [PMID:30594556]. A third paper, titled 'FZD6 triggers Wnt-signalling driven by WNT10B', is abstract-only and truncated [PMID:33497493].","molecular_requirements":"FZD6 alone was sufficient in the FRAP and co-IP assays. The co-IP also tested LRP6 separately [PMID:30594556]. SMOC-2 enhances the interaction in that system.","affinity_potency":[],"species_and_systems":"HEK293T/17 cells with human FZD6-GFP and recombinant WNT proteins, whose species is not confirmed in the text [PMID:24873871]; HEK293T co-culture IP with tagged proteins [PMID:30594556]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; the IP used co-cultured ligand-expressing and receptor-expressing cells [PMID:30594556].","caveats":"FRAP shows an effect on the receptor, not binding, and the paper's own selectivity claim is about which WNTs act on FZD6. The co-IP is of tagged overexpressed proteins. The 33497493 evidence is the title only.","key_references":[{"PMID":"24873871","why":"WNT-10B changes FZD6 mobility in FRAP (full text)"},{"PMID":"30594556","why":"Fzd6 co-precipitates Wnt10b; SMOC-2 enhances binding"},{"PMID":"33497493","why":"Title reports FZD6 triggering WNT10B-driven signalling; abstract truncated"}],"covers":["LR003468","LR006668"]},"LR011000":{"pair":"WNT10B -> FZD9:LRP5","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54924173].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Two curation rows are still pending; no paper has been judged.","key_references":[],"covers":["LR011000"]},"LR006677":{"pair":"WNT2 -> FZD6","headline":"WNT2 changes FZD6 surface mobility in live cells (FRAP); a functional readout, not binding.","interaction_type":"functional only","direction_and_effect":"Recombinant WNT-2 among WNT-1, -3A, -4, -5A, -7A, -9B and -10B affected FZD6-GFP lateral mobility, taken to mean they act on FZD6 [PMID:24873871].","molecular_requirements":"Changes in FZD6 mobility relate to Gi/o precoupling (blocked by pertussis toxin and NEM) [PMID:24873871].","affinity_potency":[],"species_and_systems":"HEK293 cells expressing FZD6-GFP, commercial recombinant WNTs; WNT species not reported in our evidence. Mouse pair ortholog-inferred.","localisation_and_range":"Wnt2 flagged secreted [flag].","caveats":"FRAP shows an effect on the receptor but not direct binding; no affinity reported.","key_references":[{"PMID":"24873871","why":"FRAP of FZD6-GFP shows WNT-2 effect"}],"covers":["LR003477","LR006677"]},"LR007559":{"pair":"WNT2 -> SFRP1","headline":"Predicted by docking; database co-IP records exist. SFRP1 is a secreted Wnt antagonist, not a signalling receptor.","interaction_type":"conflicting","direction_and_effect":"SFRP1 is classed as inhibitory here (Ligand-Ligand). Homology modelling and docking suggest Wnt2 and SFRP1 interact through thumb and finger sites [PMID:33155881].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Computational docking and molecular dynamics, no wet-lab experiment [PMID:33155881]. BioGRID and IntAct list an affinity capture-Western / anti-tag co-IP from PMID 10347172 (species not stated) [DB:BioGRID][DB:IntAct].","localisation_and_range":"Both partners are annotated as secreted [flag], so this is a soluble antagonist/decoy-type relation.","caveats":"Paper evidence is computational only. The experimental support is a database record whose paper is not in our reviewed set [DB:BioGRID][DB:IntAct]. Abstract read only.","key_references":[{"PMID":"33155881","why":"Docking model of Wnt2-SFRP1 interaction"}],"covers":["LR007559"]},"LR006686":{"pair":"WNT3 -> FZD4","headline":"Wnt3 induced signalling through FZD4 in a human cell reporter screen, a generic functional result; mouse pair is projected.","interaction_type":"functional only","direction_and_effect":"Agonist-type signalling: the paper states \"Wnt3/Wnt3a induced signaling via all FZDs, in contrast to other Wnts that were more selective\" [PMID:28733458].","molecular_requirements":"Co-receptor and subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293T FZD1,2,7 (and FZD1,2,4,5,7,8) CRISPR-mutant cells, TCF4/Wnt luciferase [PMID:28733458]; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"The sentence is generic across FZDs; specifics sit in a figure matrix not in the dossier. Functional rescue only, no binding. Many other papers were abstract_insufficient.","key_references":[{"PMID":"28733458","why":"Wnt-FZD rescue map in CRISPR FZD-mutant HEK293T cells"}],"covers":["LR003486","LR006686"]},"LR004985":{"pair":"WNT3 -> FZD8","headline":"The only curated paper concerns Wnt3A, not WNT3, and shows IGFBP-4 blocking Wnt3A binding to Frizzled 8; WNT3-FZD8 is not shown directly.","interaction_type":"database-asserted only","direction_and_effect":"IGFBP-4 physically interacted with Frizzled 8 and LRP6 and inhibited the binding of Wnt3A to them; this is inhibition by a competitor, not Wnt3 agonism [PMID:18528331].","molecular_requirements":"Not reported in our evidence for WNT3.","affinity_potency":[],"species_and_systems":"Experimental species not specified in the dossier; abstract only [PMID:18528331].","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"The paper names Wnt3A, a different ligand from WNT3, and its main finding is IGFBP-4 antagonism; it does not show a WNT3-FZD8 interaction. Abstract only.","key_references":[{"PMID":"18528331","why":"Wnt3A binding to Frz8 inhibited by IGFBP-4 (Wnt3A, not WNT3)"}],"covers":["LR001596","LR004985"]},"LR004976":{"pair":"WNT3A -> FZD5","headline":"WNT3A activates FZD5 in cells, with strong CRD binding reported; both papers are indirect for FZD5 specifically.","interaction_type":"direct binding","direction_and_effect":"WNT-3A activated the WNT-beta-catenin pathway through FZD5 in 32D cells, agonist effect [PMID:25605717]. Wnt3a induced signaling through a broad range of FZDs in a CRISPR FZD-mutant system [PMID:28733458].","molecular_requirements":"LRP6 phosphorylation accompanied activation [PMID:25605717]. Excerpts describe FZD5 and FZD8 as the most promiscuous receptors and FZD5 as effective for canonical signaling, citing prior work [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human ligand and receptor [PMID:25605717]; 32D cells and HEK293T CRISPR mutants [PMID:28733458]. Human and mouse versions are listed.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"PMID:25605717 was read as abstract only; FZD5-specific affinity is not reported in our evidence. PMID:28733458 gives a generic statement across FZDs. A UniProt/IntAct record concerns other partners of this complex [DB:UniProt] [DB:IntAct].","key_references":[{"PMID":"25605717","why":"Binding map and FZD5-dependent canonical activation by WNT-3A"},{"PMID":"28733458","why":"Wnt3a signals via FZDs in a functional rescue map"}],"covers":["LR001587","LR004976"]},"LR006695":{"pair":"WNT3A -> LRP5","headline":"Wnt3a-conditioned medium acts through LRP5 to recruit Axin and activate signalling; direct binding is only supported computationally.","interaction_type":"functional only","direction_and_effect":"LRP-5 enhances Wnt-3a effects: Wnt-3a medium translocates Axin to the membrane in an LRP-5 dependent manner and raises Axin-LRP-5 FRET within minutes [PMID:11336703]. LRP5 is a stimulatory co-receptor.","molecular_requirements":"LRP-5 works with Wnt; its intracellular domain binds Axin (the last 40 C-terminal amino acids) [PMID:11336703]. A modelling study suggests Wnt3a has a protruding loop favouring LRP5/6 binding [PMID:25425204].","affinity_potency":[],"species_and_systems":"Human LRP-5 in 3T3 and other cells with Wnt-3a conditioned medium [PMID:11336703]; docking and homology modelling [PMID:25425204]. Human pair, mouse version projected.","localisation_and_range":"LRP5 is flagged transmembrane [flag].","caveats":"No direct binding assay in our evidence. The computational paper was read as abstract only and concerns LRP6 mainly [PMID:25425204]. UniProt notes the Axin interaction is enhanced by WNT3A [DB:UniProt].","key_references":[{"PMID":"11336703","why":"Wnt-3a drives LRP-5 dependent Axin translocation"},{"PMID":"25425204","why":"modelling of Wnt3a binding to LRP5/6"}],"covers":["LR003495","LR006695"]},"LR004994":{"pair":"WNT5A -> FZD6","headline":"WNT-5A acts on FZD6 in a FRAP mobility assay and in human genetics; evidence is functional, with no direct binding data.","interaction_type":"functional only","direction_and_effect":"WNT-5A increased the mobile fraction of FZD6-GFP in HEK293 cells in a pertussis-toxin- and NEM-sensitive way, consistent with Gi/o coupling [PMID:24873871]. Human fibroblasts with an FZD6 nonsense mutation responded aberrantly to WNT-5A [PMID:21665003]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Gi/o G-protein coupling was needed for the receptor mobility effect [PMID:24873871]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse reagents in HEK293 cells for FRAP [PMID:24873871]; human fibroblasts and Fzd6-/- mice [PMID:21665003]. The dossier includes a human pair and an ortholog-inferred mouse pair.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"The assay class of direct_binding for PMID 24873871 is not supported: the evidence sentence is a background statement that WNT-5A is known to functionally interact with FZD6, while the paper's own result is a mobility effect. PMID 21665003 was read as abstract only.","key_references":[{"PMID":"24873871","why":"FRAP shows WNT-5A changes FZD6 mobility via Gi/o"},{"PMID":"21665003","why":"FZD6 mutation alters fibroblast response to WNT-5A"}],"covers":["LR001605","LR004994"]},"LR007694":{"pair":"WNT5A -> FZD9:LRP6","headline":"Database-asserted only: one BioGRID record; no verified paper for the FZD9:LRP6 complex.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"BioGRID records LRP6-WNT5A by affinity capture-Western [DB:BioGRID 692083]; FZD9 is not tested in this record.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Judged rows were review-only, abstract_insufficient or different_entity; none verified the pair.","key_references":[],"covers":["LR007694"]},"LR008099":{"pair":"WNT9A -> FZD8:LRP6","headline":"WNT9A-FZD8 is supported by a single prostate-cancer abstract; binding is stated but not shown in our evidence.","interaction_type":"functional only","direction_and_effect":"Castration enhanced FZD8 binding to Wnt9A and mediated cellular plasticity by activating the non-canonical Wnt (FZD8/FYN/STAT3) pathway [PMID:37771187].","molecular_requirements":"Co-receptor LRP6 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Prostate cancer cells (species not stated in the abstract) [PMID:37771187].","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Abstract only; the binding assay is not described. The effect is non-canonical signalling after YY1-driven FZD8 transcription, so the evidence is context-specific. A second judged row was abstract_insufficient.","key_references":[{"PMID":"37771187","why":"Reports enhanced FZD8-Wnt9A binding and FZD8/FYN/STAT3 signalling in prostate cancer cells."}],"covers":["LR008099"]},"LR006794":{"pair":"YARS1 -> CXCR1","headline":"Database-asserted only: GtoPdb lists an agonist interaction; no verified paper support in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists YARS1 (cytokine domain of tyrosyl tRNA synthetase) as an agonist of CXCR1 [DB:GtoPdb]. No curator-verified paper supports this.","molecular_requirements":"Not reported in our evidence. The ligand entity is the cytokine domain of tyrosyl tRNA synthetase, not the full-length enzyme [flag].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence; no secretion flag is set for the ligand [flag].","caveats":"Rests on a single GtoPdb record with no affinity. Two papers were judged abstract-insufficient and one concerned a different entity, so none verified the pair.","key_references":[],"covers":["LR006794"]},"LR001979":{"pair":"SIRPB2 -> CD47","headline":"SIRPbeta2 binds CD47 and mediates T cell adhesion and costimulation; one abstract-read paper plus database records.","interaction_type":"direct binding","direction_and_effect":"SIRPbeta2 on T cells binds CD47 on antigen-presenting cells, mediating adhesion and enhancing antigen-specific T-cell proliferation, a costimulatory effect [PMID:15383453].","molecular_requirements":"Not reported in our evidence beyond single SIRPbeta2 and CD47 chains.","affinity_potency":[],"species_and_systems":"Human T cells and NK cells; adhesion and proliferation assays [PMID:15383453]. IntAct lists FACS and solid phase assay records [DB:IntAct].","localisation_and_range":"Ligand flagged not secreted and CD47 flagged transmembrane [flag], consistent with contact-dependent (juxtacrine) signalling.","caveats":"One paper, read as an abstract. Reactome entries are for SIRP family or SIRP gamma:CD47 complexes, not SIRPbeta2 specifically [DB:Reactome].","key_references":[{"PMID":"15383453","why":"SIRPbeta2 binds CD47 and costimulates T cells"}],"covers":["LR001979"]},"LR008459":{"pair":"IAPP -> RAMP2","headline":"Amylin acts through a calcitonin receptor:RAMP2 complex; RAMP2 is an accessory subunit, not a standalone receptor.","interaction_type":"functional only","direction_and_effect":"Amylin is an agonist. Human and rat amylin activated the calcitonin receptor alone and all three CALCR+RAMP complexes in cAMP assays [PMID:24169554]. GtoPdb lists a full agonist action [DB:GtoPdb].","molecular_requirements":"RAMP2 needs the calcitonin receptor (CTRa) to form an amylin receptor. The RAMP N-terminal domain mainly dictates peptide specificity in binding [PMID:16531504]. UniProt notes RAMP2 with CALCR acts as an amylin receptor complex [DB:UniProt]. A PDB structure exists [DB:PDB 9BQ3].","affinity_potency":[],"species_and_systems":"Human CTRa with chimeric RAMPs in COS-7 cells [PMID:16531504]; HEK293S and COS-7 cells [PMID:24169554]. Pair is human.","localisation_and_range":"Amylin is annotated secreted [flag], so hormone-like paracrine or endocrine action.","caveats":"Both papers read as abstract only. Neither isolates RAMP2 alone; GtoPdb potency values are available but not quoted here. Reactome describes AMY1-3 binding IAPP(34-70) [DB:Reactome].","key_references":[{"PMID":"16531504","why":"RAMP1/RAMP2 chimeras with CTRa, amylin binding and cAMP."},{"PMID":"24169554","why":"Amylin activates AMY receptors including RAMP2-containing."}],"covers":["LR008459"]}};